    date:{day:1,month:1,year:2026},
    political:{approval:c.approval,stability:66,confidence:56,mandateStartYear:2025,term:'Mandat en cours',ruling:c.ruling,electionDate:`${c.electionYear}-04-15`,seatBlocks:(()=>{const blocks=structuredClone(SEAT_BLOCKS);const scale=c.seats/577;blocks.forEach(b=>b.seats=Math.round(b.seats*scale));blocks[0].seats+=c.seats-blocks.reduce((n,b)=>n+b.seats,0);return blocks;})(),oppositionPressure:37,campaignFund:12,polling:{incumbent:c.approval,opposition:Math.max(0,92-c.approval),undecided:8,turnout:69},lastElection:null},
    society:{population:c.population,unemployment:c.unemployment,inflation:c.inflation,growth:c.growth,inequality:31,poverty:14.5,lifeExpectancy:82.1,renewables:23.4,education:79.2,health:77.5,migration:0.12,crime:42},
    economy:{gdp:c.gdp,productivity:1.2,confidence:101.2,exports:c.gdp*.31,imports:c.gdp*.34,baseRevenueShare:({'france':.205,'germany':.19,'usa':.10,'canada':.16,'japan':.20,'brazil':.14}[countryKey]||.18)},
    finance:{cash:c.cash,debt:c.debt,creditRating:'AA',tax:{...c.tax},ministries:MINISTRIES_DEFAULT.map(m=>({...m,budget:round1(m.budget*({'france':1,'germany':1.462,'usa':7.451,'canada':.642,'japan':1.283,'brazil':.657}[countryKey]||c.gdp/2900))})),bonds:[],transactions:[{id:'tx-init',date:'01/01/2026',label:'Trésorerie de début de mandat',category:'Ouverture',amount:c.cash,balance:c.cash}],debtHistory:[c.debt],balanceHistory:[],revenueHistory:[],spendHistory:[],otherRevenue:80,loanRate:3.2},
