function clone(obj){return JSON.parse(JSON.stringify(obj));}
function recalculate(s){
  const tax=s.finance.tax, gdp=Math.max(1,s.economy.gdp);
  const share=s.economy.baseRevenueShare + (Number(tax.income)*.70+Number(tax.corporate)*.12+Number(tax.vat)*.65+Number(tax.fuel)*.12)/100;
  s.finance.revenue=round1(gdp*share+s.finance.otherRevenue);
  s.finance.expenses=round1(s.finance.ministries.reduce((n,m)=>n+Number(m.budget||0),0));
  s.finance.balance=round1(s.finance.revenue-s.finance.expenses);
  s.finance.debtRatio=round1(s.finance.debt/gdp*100);
  s.finance.deficitRatio=round1(Math.abs(Math.min(0,s.finance.balance))/gdp*100);
  s.economy.exports=round1(gdp*(.31+Math.max(-.08,Math.min(.08,(s.diplomacy.deals.length*.003)))));
  s.economy.imports=round1(gdp*Math.max(.05,.34-s.diplomacy.deals.length*.001-(Number(s.diplomacy.tariff||0)-3)*.0005));
  s.economy.tradeBalance=round1(s.economy.exports-s.economy.imports);
  s.parliament.totalSeats=s.country.seats;
  s.parliament.majorityThreshold=Math.floor(s.country.seats/2)+1;
}
function round1(n){return Math.round((Number(n)||0)*10)/10;}
function money(n, decimals=1){const cur=app?.state?.country?.currency||'€'; const abs=Math.abs(n); let v=abs; let suffix=' Md'; if(abs>=1000){v=abs/1000;suffix=' billions de milliers';} if(abs<10)v=Number(v).toLocaleString('fr-FR',{maximumFractionDigits:decimals});else v=Math.round(v).toLocaleString('fr-FR'); return `${n<0?'−':''}${v}${suffix===' billions de milliers'?' T':suffix} ${cur}`;}
function billion(n, decimals=1){return `${Number(n||0).toLocaleString('fr-FR',{minimumFractionDigits:decimals,maximumFractionDigits:decimals})} Md ${app.state.country.currency}`;}
function pct(n,d=1){return `${Number(n||0).toLocaleString('fr-FR',{minimumFractionDigits:d,maximumFractionDigits:d})} %`;}
function integer(n){return Math.round(Number(n)||0).toLocaleString('fr-FR');}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function dstr(date=app.state.date){const months=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];return `${date.day} ${months[date.month-1]} ${date.year}`;}
function dshort(){return `${String(app.state.date.day).padStart(2,'0')}/${String(app.state.date.month).padStart(2,'0')}/${app.state.date.year}`;}
function makeId(prefix='id'){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;}
function eventLog(title,description,type='decision',impact='neutral'){const s=app.state;s.events.unshift({id:makeId('e'),date:dstr(),type,title,description,impact});s.events=s.events.slice(0,250);}
function saveState(silent=true){if(app.state?.settings?.autoSave===false&&silent)return;try{app.state.lastSaved=new Date().toISOString();localStorage.setItem(SAVE_KEY,JSON.stringify(app.state));const status=document.getElementById('saveStatus');if(status)status.textContent=`Sauvegardé à ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}`;if(!silent)toast('Sauvegarde enregistrée sur cet appareil.','success');}catch(e){toast('Impossible de sauvegarder : stockage local indisponible.','error');}}
function loadState(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;const parsed=JSON.parse(raw);if(parsed.version!==3||!parsed.country||!parsed.finance)return null;const base=freshState(COUNTRIES[parsed.countryKey]?parsed.countryKey:'france');return {...base,...parsed,country:{...base.country,...parsed.country},date:{...base.date,...parsed.date},political:{...base.political,...parsed.political,polling:{...base.political.polling,...(parsed.political?.polling||{})},seatBlocks:parsed.political?.seatBlocks||base.political.seatBlocks,campaignFund:parsed.political?.campaignFund??base.political.campaignFund},society:{...base.society,...parsed.society},economy:{...base.economy,...parsed.economy},finance:{...base.finance,...parsed.finance,tax:{...base.finance.tax,...(parsed.finance?.tax||{})},ministries:parsed.finance?.ministries||base.finance.ministries,bonds:parsed.finance?.bonds||[],transactions:parsed.finance?.transactions||base.finance.transactions},procurement:{...base.procurement,...parsed.procurement,stock:{...base.procurement.stock,...(parsed.procurement?.stock||{})},orders:parsed.procurement?.orders||[]},defense:{...base.defense,...parsed.defense,units:parsed.defense?.units||base.defense.units,missions:parsed.defense?.missions||[]},diplomacy:{...base.diplomacy,...parsed.diplomacy,relations:{...base.diplomacy.relations,...(parsed.diplomacy?.relations||{})},deals:parsed.diplomacy?.deals||[]},cabinet:parsed.cabinet||base.cabinet,projects:parsed.projects||base.projects,bills:parsed.bills||[],events:parsed.events||base.events,alerts:parsed.alerts||[],settings:{...base.settings,...parsed.settings},preferences:{...base.preferences,...parsed.preferences}};}catch(e){return null;}}
const app={state:loadState()||freshState(),page:'overview',map:null,mapMarkers:new Map(),mapRoutes:new Map(),mapReady:false,mapClickArmed:false,toastTimer:null,selectedBillFilter:'all'};
if(!app.state.country)app.state=freshState();

function toast(message,type=''){const r=document.getElementById('toastRegion');const t=document.createElement('div');t.className=`toast ${type}`;t.textContent=message;r.appendChild(t);setTimeout(()=>t.remove(),3700);}
function metric(label,value,note,mark,tag=''){return `<div class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-mark">${mark}</span></div><div class="metric-value">${value}</div><div class="metric-note">${tag?`<span class="${tag.includes('−')||tag.includes('déficit')?'delta-bad':'delta-good'}">${tag}</span>`:''}${note?`<span>${note}</span>`:''}</div></div>`;}
function card(title,subtitle,body,footer=''){return `<section class="card"><div class="card-header"><div><h3 class="card-title">${title}</h3>${subtitle?`<div class="card-subtitle">${subtitle}</div>`:''}</div></div><div class="card-body">${body}</div>${footer?`<div class="card-footer">${footer}</div>`:''}</section>`;}
function sectionHead(title,subtitle,actions=''){return `<div class="section-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="section-actions">${actions}</div>`:''}</div>`;}
function emptyState(title,desc,btn=''){return `<div class="empty-state"><strong>${title}</strong><p>${desc}</p>${btn}</div>`;}
function statusTag(status){const map={ 'En cours':'tag-blue','En préparation':'tag-amber','Terminé':'tag-green','Suspendu':'tag-red','Adopté':'tag-green','Promulgué':'tag-green','Rejeté':'tag-red','À l’étude':'tag-amber','En lecture':'tag-blue','À signer':'tag-amber','En alerte':'tag-amber','Opérationnel':'tag-green','En manœuvre':'tag-blue','Soutien':'tag','Patrouille':'tag-blue','En négociation':'tag-amber','Signé':'tag-green','Livrée':'tag-green','Annulée':'tag-red','Actif':'tag-green','Brouillon':'tag'};return `<span class="tag ${map[status]||'tag'}">${esc(status)}</span>`;}
function ministrySpend(s){return s.finance.ministries.reduce((n,m)=>n+Number(m.budget||0),0);}
function approvalClass(v){return v>=55?'green':v>=40?'amber':'red';}
function sparkline(values){const v=values.length?values:[0,1];const min=Math.min(...v),max=Math.max(...v);const pts=v.map((n,i)=>`${i/(v.length-1||1)*80},${25-((n-min)/(max-min||1))*22}`).join(' ');return `<svg class="sparkline" viewBox="0 0 80 28" aria-hidden="true"><polyline fill="none" stroke="#7899b3" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${pts}"/></svg>`;}
function budgetBars(){const hist=app.state.finance.spendHistory.length?app.state.finance.spendHistory:[app.state.finance.expenses*.96,app.state.finance.expenses*.99,app.state.finance.expenses];const labels=['M−2','M−1','Actuel'];const max=Math.max(...hist,1);return `<div class="chart-bars">${hist.slice(-6).map((v,i)=>`<div class="chart-bar-col"><div class="chart-bar ${i<hist.length-1?'alt':''}" style="height:${Math.max(3,v/max*100)}%" title="${billion(v)}"></div><span class="chart-month">${labels[i]||`M−${hist.length-i-1}`}</span></div>`).join('')}</div>`;}
function render(){recalculate(app.state);const [eye,title]=PAGE_INFO[app.page]||PAGE_INFO.overview;document.getElementById('sectionEyebrow').textContent=eye;document.getElementById('pageTitle').textContent=title;document.getElementById('countryName').textContent=app.state.country.name;document.getElementById('countryFlag').textContent=app.state.country.flag;document.getElementById('countrySubtitle').textContent=`Mandat présidentiel · ${app.state.date.year}`;document.getElementById('simDate').textContent=dstr();document.getElementById('billCount').textContent=app.state.bills.filter(b=>!['Promulgué','Rejeté','Retiré'].includes(b.status)).length;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===app.page));const target=document.getElementById('pageContent');target.innerHTML=renderPage();if(app.page==='defense')requestAnimationFrame(()=>initMap());if(app.state.alerts.length)document.getElementById('alertDot').style.display='block';else document.getElementById('alertDot').style.display='none';if(app.state.settings.autoSave)saveState(true);}
function renderPage(){switch(app.page){case'overview':return pageOverview();case'society':return pageSociety();case'finance':return pageFinance();case'taxes':return pageTaxes();case'bills':return pageBills();case'parliament':return pageParliament();case'elections':return pageElections();case'projects':return pageProjects();case'procurement':return pageProcurement();case'cabinet':return pageCabinet();case'defense':return pageDefense();case'diplomacy':return pageDiplomacy();case'events':return pageEvents();case'save':return pageSave();default:return pageOverview();}}
function pageOverview(){const s=app.state;const bal=s.finance.balance;const upcoming=s.bills.filter(b=>!['Promulgué','Rejeté','Retiré'].includes(b.status)).slice(0,3);const topEvents=s.events.slice(0,4);const debtHist=s.finance.debtHistory.slice(-8);return `
  <div class="hero-strip"><div><div class="eyebrow" style="color:#b8c7d4">POINT DE SITUATION · ${dshort()}</div><h2>Bonjour, Monsieur le Président.</h2><p>Le pays est en phase de gouvernance active. Consultez les comptes publics, arbitrez les priorités et suivez les dossiers qui nécessitent une décision.</p></div><div class="hero-kpi"><small>POPULARITÉ NATIONALE</small><strong>${pct(s.political.approval,0)}</strong><span class="tag ${s.political.approval>=50?'tag-green':'tag-amber'}">${s.political.approval>=50?'Confiance relative':'Opinion fragile'}</span></div></div>
  <div class="grid grid-4">${metric('PRODUIT INTÉRIEUR BRUT',billion(s.economy.gdp,0),`croissance ${pct(s.society.growth)}`,'↗',s.society.growth>=0?'+ économie':'− économie')}${metric('RECETTES ANNUELLES',billion(s.finance.revenue,0),'prévision fiscale','↓')}${metric('DÉPENSES PUBLIQUES',billion(s.finance.expenses,0),'crédits votés','↑')}${metric('DETTE PUBLIQUE',billion(s.finance.debt,0),`${pct(s.finance.debtRatio)} du PIB`,'▤',`${s.finance.balance<0?'déficit':'excédent'} ${billion(Math.abs(s.finance.balance),0)}`)}</div>
  <div class="dashboard-grid mt-12"><div class="stack">
    <section class="card"><div class="card-header"><div><h3 class="card-title">Équilibre des finances publiques</h3><div class="card-subtitle">Budget annuel, en milliards ${esc(s.country.currency)}</div></div><button class="button button-secondary button-sm" data-page="finance">Ouvrir les comptes ↗</button></div><div class="card-body"><div class="grid grid-2"><div><div class="metric-label">SOLDE BUDGÉTAIRE</div><div class="metric-value" style="font-size:25px;color:${bal>=0?'var(--green)':'var(--red)'}">${bal<0?'−':''}${billion(Math.abs(bal),1)}</div><div class="metric-note">${bal>=0?'Excédent prévisionnel':'Déficit annuel prévisionnel'} · ${pct(Math.abs(bal)/s.economy.gdp*100)} du PIB</div>${budgetBars()}</div><div class="stat-list"><div><div class="stat-row"><span class="stat-row-label">Recettes</span><span class="stat-row-value">${billion(s.finance.revenue)}</span></div><div class="progress-track"><div class="progress-fill green" style="width:${Math.min(100,s.finance.revenue/(Math.max(s.finance.revenue,s.finance.expenses))*100)}%"></div></div></div><div><div class="stat-row"><span class="stat-row-label">Dépenses</span><span class="stat-row-value">${billion(s.finance.expenses)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,s.finance.expenses/(Math.max(s.finance.revenue,s.finance.expenses))*100)}%"></div></div></div><div><div class="stat-row"><span class="stat-row-label">Trésorerie disponible</span><span class="stat-row-value">${billion(s.finance.cash)}</span></div><div class="progress-track"><div class="progress-fill amber" style="width:${Math.max(2,Math.min(100,s.finance.cash/Math.max(1,s.finance.expenses)*100*8))}%"></div></div></div><div><div class="stat-row"><span class="stat-row-label">Charge annuelle de la dette</span><span class="stat-row-value">${billion(s.finance.ministries.find(m=>m.id==='debt')?.budget||0)}</span></div><div class="progress-track"><div class="progress-fill red" style="width:${Math.min(100,(s.finance.ministries.find(m=>m.id==='debt')?.budget||0)/s.finance.expenses*100*4)}%"></div></div></div></div></div></div></section>
    <section class="card"><div class="card-header"><div><h3 class="card-title">Dossiers législatifs à arbitrer</h3><div class="card-subtitle">Projets en attente d'une décision de l'exécutif ou du Parlement</div></div><button class="button button-secondary button-sm" data-page="bills">Tous les textes ↗</button></div><div class="card-body">${upcoming.length?upcoming.map(b=>`<div class="list-row"><div class="list-icon">§</div><div class="list-content"><div class="list-title">${esc(b.title)}</div><div class="list-desc">${esc(b.sector)} · ${esc(b.summary)}</div><div class="list-meta">Coût estimé ${billion(b.cost)} / an · Soutien estimé ${pct(b.support,0)}</div></div>${statusTag(b.status)}</div>`).join(''):emptyState('Aucun texte en attente','Déposez un projet de loi pour engager une réforme.',`<button class="button button-primary button-sm" data-action="new-bill">Créer un projet de loi</button>`)}</div></section>
  </div><div class="stack">
    <section class="card"><div class="card-header"><div><h3 class="card-title">Indicateurs nationaux</h3><div class="card-subtitle">Derniers chiffres connus de la simulation</div></div><button class="button button-secondary button-sm" data-page="society">Détails ↗</button></div><div class="card-body"><div class="stat-list">${statLine('Popularité',s.political.approval,100,pct(s.political.approval,0),'blue')}${statLine('Stabilité institutionnelle',s.political.stability,100,pct(s.political.stability,0),'green')}${statLine('Chômage',s.society.unemployment,20,pct(s.society.unemployment),'amber')}${statLine('Inflation',s.society.inflation,10,pct(s.society.inflation),'amber')}${statLine('Croissance annuelle',Math.max(0,s.society.growth+3),6,pct(s.society.growth),'green')}</div></div></section>
    <section class="card"><div class="card-header"><div><h3 class="card-title">Journal de la présidence</h3><div class="card-subtitle">Décisions et événements récents</div></div><button class="button button-secondary button-sm" data-page="events">Tout voir ↗</button></div><div class="card-body">${topEvents.length?topEvents.map((e,i)=>`<div class="timeline-item"><span class="timeline-marker"></span><div class="timeline-date">${esc(e.date)}</div><div class="timeline-title">${esc(e.title)}</div><div class="timeline-desc">${esc(e.description)}</div></div>`).join(''):emptyState('Journal vide','Les décisions apparaîtront ici.')}</div></section>
  </div></div>`;}
function statLine(label,value,max,txt,color='blue'){return `<div><div class="stat-row"><span class="stat-row-label">${label}</span><span class="stat-row-value">${txt}</span></div><div class="progress-track"><div class="progress-fill ${color}" style="width:${Math.max(1,Math.min(100,Number(value)/max*100))}%"></div></div></div>`;}
function pageSociety(){const s=app.state;return `${sectionHead('Indicateurs du pays','Modifiez les hypothèses socio-économiques pour construire votre trajectoire nationale.',`<button class="button button-primary" data-action="edit-society">Modifier les indicateurs</button>`)}<div class="grid grid-4">${metric('POPULATION',`${Number(s.society.population).toLocaleString('fr-FR')} M`,'habitants','◎')}${metric('CHÔMAGE',pct(s.society.unemployment),'population active','⌁')}${metric('INFLATION',pct(s.society.inflation),'indice des prix','％')}${metric('CROISSANCE',pct(s.society.growth),'variation annuelle du PIB','↗',s.society.growth>=0?'+ activité':'− activité')}</div><div class="grid grid-2 mt-12">${card('Données socio-économiques','Hypothèses de la simulation',`<div class="stat-list">${statLine('Indice d’inégalité (sur 100)',s.society.inequality,100,integer(s.society.inequality),'amber')}${statLine('Taux de pauvreté',s.society.poverty,40,pct(s.society.poverty),'red')}${statLine('Espérance de vie',s.society.lifeExpectancy,100,`${s.society.lifeExpectancy.toLocaleString('fr-FR')} ans`,'green')}${statLine('Énergies renouvelables',s.society.renewables,100,pct(s.society.renewables),'green')}${statLine('Accès à l’éducation',s.society.education,100,pct(s.society.education),'blue')}${statLine('Accès aux soins',s.society.health,100,pct(s.society.health),'green')}</div>`)}${card('Perspectives économiques','Indicateurs utiles au pilotage',`<div class="two-col-stat"><div class="mini-stat"><small>PIB courant</small><strong>${billion(s.economy.gdp,0)}</strong><span>valeur annuelle simulée</span></div><div class="mini-stat"><small>Productivité</small><strong>${pct(s.economy.productivity)}</strong><span>progression annuelle</span></div><div class="mini-stat"><small>Confiance des entreprises</small><strong>${Number(s.economy.confidence).toLocaleString('fr-FR')}</strong><span>indice base 100</span></div><div class="mini-stat"><small>Migration nette</small><strong>${s.society.migration>0?'+':''}${s.society.migration} %</strong><span>de la population / an</span></div></div><div class="divider"></div><div class="callout-blue"><strong>Comment lire ces indicateurs</strong>Les indicateurs sont des valeurs de départ pour le jeu. Les politiques, les décisions budgétaires et l'avancée du temps peuvent les faire évoluer.</div>`)} </div>`;}
function pageFinance(){const s=app.state;const total=s.finance.expenses||1;return `${sectionHead('Trésor public','Arbitrez les dépenses, contractez des emprunts, gérez les remboursements et suivez votre trajectoire budgétaire.',`<button class="button button-secondary" data-action="export-finance">Exporter les comptes CSV</button><button class="button button-primary" data-action="open-borrow">+ Contracter un emprunt</button>`)}<div class="grid grid-4">${metric('SOLDE ANNUEL',`${s.finance.balance<0?'−':''}${billion(Math.abs(s.finance.balance))}`,s.finance.balance>=0?'excédent prévisionnel':'déficit prévisionnel','↔',s.finance.balance>=0?'excédent':'déficit')}${metric('TRÉSORERIE',billion(s.finance.cash),'disponible immédiatement','▤')}${metric('DETTE TOTALE',billion(s.finance.debt),`${pct(s.finance.debtRatio)} du PIB`,'↻')}${metric('COÛT DE FINANCEMENT',pct(s.finance.loanRate),'taux indicatif des nouveaux emprunts','％')}</div><div class="grid grid-2 mt-12"><div class="stack">${card('Répartition des dépenses','Crédits annuels par mission',`<div class="table-wrap"><table><thead><tr><th>Mission</th><th>Crédit annuel (Md)</th><th>Part</th><th></th></tr></thead><tbody>${s.finance.ministries.map(m=>`<tr><td><div class="table-strong">${esc(m.name)}</div><div class="table-muted">${esc(m.priority==='fixed'?'Dépense rigide':m.priority==='high'?'Priorité nationale':'Crédit ajustable')}</div></td><td class="numeric">${Number(m.budget).toLocaleString('fr-FR',{maximumFractionDigits:1})}</td><td style="min-width:95px"><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,m.budget/total*100*4)}%"></div></div><div class="table-muted">${pct(m.budget/total*100)}</div></td><td><button class="button button-secondary button-sm" data-action="edit-ministry" data-id="${m.id}">Modifier</button></td></tr>`).join('')}</tbody></table></div>`,`<span class="small-note">Les montants sont en milliards ${esc(s.country.currency)} par an. Toute modification affecte le solde budgétaire.</span><button class="button button-secondary button-sm" data-action="edit-budget-all">Modifier tous les crédits</button>`)}${card('Dernières opérations du Trésor','Journal de trésorerie',`${s.finance.transactions.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Opération</th><th>Montant</th></tr></thead><tbody>${s.finance.transactions.slice(0,8).map(t=>`<tr><td class="mono">${esc(t.date)}</td><td><div class="table-strong">${esc(t.label)}</div><div class="table-muted">${esc(t.category)}</div></td><td class="numeric" style="color:${t.amount>=0?'var(--green)':'var(--red)'}">${t.amount>=0?'+':'−'}${billion(Math.abs(t.amount))}</td></tr>`).join('')}</tbody></table></div>`:emptyState('Pas encore de mouvement','Les opérations apparaîtront à chaque décision financière.')}`)}</div><div class="stack">${card('Synthèse des comptes','Prévision annuelle à politique inchangée',`<div class="stat-list"><div class="stat-row"><span class="stat-row-label">Recettes totales</span><span class="stat-row-value">${billion(s.finance.revenue)}</span></div><div class="stat-row"><span class="stat-row-label">Dépenses totales</span><span class="stat-row-value">${billion(s.finance.expenses)}</span></div><div class="stat-row"><span class="stat-row-label">Solde budgétaire</span><span class="stat-row-value" style="color:${s.finance.balance<0?'var(--red)':'var(--green)'}">${s.finance.balance<0?'−':''}${billion(Math.abs(s.finance.balance))}</span></div><div class="stat-row"><span class="stat-row-label">Solde / PIB</span><span class="stat-row-value">${pct(s.finance.balance/s.economy.gdp*100)}</span></div><div class="stat-row"><span class="stat-row-label">Dette / PIB</span><span class="stat-row-value">${pct(s.finance.debtRatio)}</span></div><div class="stat-row"><span class="stat-row-label">Notation de crédit</span><span class="tag tag-blue">${esc(s.finance.creditRating)}</span></div></div><div class="divider"></div><div class="notice"><span class="notice-icon">!</span><div><strong>${s.finance.balance<0?'Attention au déficit structurel':'Équilibre budgétaire favorable'}</strong><p>${s.finance.balance<0?'Le déficit augmente la dette au fil du temps si le solde n’est pas redressé.':'Les excédents peuvent être affectés au désendettement ou à l’investissement.'}</p></div></div>`)}${card('Emprunts et obligations','Dette contractée par votre gouvernement',s.finance.bonds.length?`<div class="table-wrap"><table><thead><tr><th>Contrat</th><th>Capital</th><th>Taux</th><th>Échéance</th><th></th></tr></thead><tbody>${s.finance.bonds.map(b=>`<tr><td><div class="table-strong">${esc(b.label)}</div><div class="table-muted">${esc(b.date)}</div></td><td class="numeric">${billion(b.principal)}</td><td class="numeric">${pct(b.rate)}</td><td>${esc(b.term)} ans</td><td><button class="button button-secondary button-sm" data-action="repay-bond" data-id="${b.id}">Rembourser</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('Aucun nouvel emprunt','Vous pouvez émettre une obligation ou contracter un emprunt pour renforcer la trésorerie.',`<button class="button button-primary button-sm" data-action="open-borrow">Étudier un financement</button>`))}</div></div>`;}
function pageTaxes(){const s=app.state,t=s.finance.tax;return `${sectionHead('Barèmes fiscaux','Ajustez les taux et mesurez l’effet estimé sur les recettes. Les modifications sont immédiates dans le modèle.',`<button class="button button-secondary" data-action="reset-taxes">Restaurer les taux initiaux</button>`)}<div class="grid grid-3">${metric('RECETTES ESTIMÉES',billion(s.finance.revenue),'après application des barèmes','↓')}${metric('SOLDE BUDGÉTAIRE',`${s.finance.balance<0?'−':''}${billion(Math.abs(s.finance.balance))}`,'recettes moins dépenses','↔')}${metric('TAXES / PIB',pct((s.finance.revenue-s.finance.otherRevenue)/s.economy.gdp*100),'estimation de recettes','％')}</div><div class="grid grid-2 mt-12"><section class="card"><div class="card-header"><div><h3 class="card-title">Paramètres de fiscalité</h3><div class="card-subtitle">Taux nominaux en pourcentage</div></div><span class="tag tag-blue">Modifiables</span></div><div class="card-body"><form id="taxForm" data-form="tax"><div class="form-grid">${taxField('income','Impôt sur le revenu',t.income,'0','60','Barème effectif simplifié du modèle')}${taxField('corporate','Impôt sur les sociétés',t.corporate,'0','50','Taux nominal')}${taxField('vat','Taxe sur la consommation / TVA',t.vat,'0','35','Taux standard')}${taxField('fuel','Accises carburants',t.fuel,'0','60','Indice de taxation assimilé à un taux') }</div><div class="callout-blue mt-12"><strong>Effet dans le jeu</strong>Les nouveaux taux recalculent immédiatement les recettes simulées. L’évolution future de l’activité et de la popularité dépendra aussi des mesures adoptées.</div><div class="form-actions"><button class="button button-primary" type="submit">Appliquer les barèmes</button></div></form></div></section><div class="stack">${card('Effet marginal estimé','Variation par rapport au taux actuel',`<div class="stat-list">${Object.entries(t).map(([k,v])=>`<div><div class="stat-row"><span class="stat-row-label">${({income:'Impôt sur le revenu',corporate:'Impôt sur les sociétés',vat:'TVA',fuel:'Accises carburants'})[k]||k}</span><span class="stat-row-value">${pct(v)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,v/60*100)}%"></div></div></div>`).join('')}</div><div class="divider"></div><p class="small-note">Le modèle agrège l’assiette imposable et ne représente pas une simulation comptable certifiée.</p>`)}${card('Arbitrage fiscal','Conséquences typiques à prendre en compte',`<div class="list-row"><div class="list-icon">＋</div><div class="list-content"><div class="list-title">Hausse d’un taux</div><div class="list-desc">Peut augmenter les recettes à court terme, mais aussi peser sur la consommation, l’investissement ou l’adhésion publique.</div></div></div><div class="list-row"><div class="list-icon">−</div><div class="list-content"><div class="list-title">Baisse d’un taux</div><div class="list-desc">Peut soutenir le pouvoir d’achat ou l’activité, au prix d’une baisse initiale des recettes.</div></div></div><div class="list-row"><div class="list-icon">§</div><div class="list-content"><div class="list-title">Cadre législatif</div><div class="list-desc">Pour formaliser la réforme, créez un projet de loi puis faites-le examiner au Parlement.</div><button class="button button-secondary button-sm mt-12" data-action="new-bill" data-sector="Fiscalité">Créer un projet fiscal</button></div></div>`)}</div></div>`;}
function taxField(id,label,val,min,max,help){return `<div class="field"><label for="tax-${id}">${label}</label><div class="inline-control"><input id="tax-${id}" name="${id}" type="number" min="${min}" max="${max}" step="0.1" value="${val}" required><span class="small-note">%</span></div><small>${help}</small></div>`;}
function pageBills(){const s=app.state;const statuses={'all':'Tous','Brouillon':'Brouillons','En lecture':'1re lecture','Seconde lecture':'2e lecture','À signer':'À promulguer','Promulgué':'Promulgués','Rejeté':'Rejetés'};let list=s.bills.filter(b=>app.selectedBillFilter==='all'||b.status===app.selectedBillFilter);return `${sectionHead('Registre législatif','Créez, modifiez, déposez, votez et promulguez vos textes. Les votes prennent en compte les rapports de force et l’opinion.',`<button class="button button-secondary" data-action="export-bills">Exporter le registre</button><button class="button button-primary" data-action="new-bill">+ Nouveau projet de loi</button>`)}<div class="pill-tabs">${Object.entries(statuses).map(([key,label])=>`<button class="pill-tab ${app.selectedBillFilter===key?'active':''}" data-action="filter-bills" data-value="${key}">${label} <span class="muted">(${key==='all'?s.bills.length:s.bills.filter(b=>b.status===key).length})</span></button>`).join('')}</div>${list.length?list.map(b=>billCard(b)).join(''):emptyState('Aucun texte dans cette catégorie','Vous pouvez rédiger une initiative, définir ses coûts et la soumettre à la procédure parlementaire.',`<button class="button button-primary" data-action="new-bill">Rédiger un projet de loi</button>`)}<div class="callout-blue mt-12"><strong>Procédure parlementaire simplifiée</strong>Un texte est d’abord rédigé, puis soumis au vote d’une chambre, examiné par la seconde chambre avant promulgation. La procédure reste une abstraction de jeu.</div>`;}
function billCard(b){const stageMap={Brouillon:0,'En lecture':1,'Seconde lecture':2,'À signer':3,'Promulgué':4,'Rejeté':-1,'Retiré':-1};const stage=stageMap[b.status]??0;const actions=[];if(b.status==='Brouillon')actions.push(`<button class="button button-primary button-sm" data-action="submit-bill" data-id="${b.id}">Déposer au Parlement</button>`);if(['En lecture','Seconde lecture'].includes(b.status))actions.push(`<button class="button button-primary button-sm" data-action="vote-bill" data-id="${b.id}">${b.status==='En lecture'?'Vote en première lecture':'Vote en seconde lecture'}</button>`);if(b.status==='À signer')actions.push(`<button class="button button-primary button-sm" data-action="promulgate-bill" data-id="${b.id}">Promulguer</button>`);if(['Brouillon','En lecture'].includes(b.status))actions.push(`<button class="button button-secondary button-sm" data-action="edit-bill" data-id="${b.id}">Modifier</button>`);if(!['Promulgué','Rejeté','Retiré'].includes(b.status))actions.push(`<button class="button button-secondary button-sm" data-action="withdraw-bill" data-id="${b.id}">Retirer</button>`);return `<article class="bill-card"><div class="bill-top"><div><div class="bill-title">${esc(b.title)}</div><div class="bill-summary">${esc(b.summary)}</div><div class="bill-meta"><span><b>Catégorie :</b> ${esc(b.sector)}</span><span><b>Coût annuel :</b> ${billion(b.cost)}</span><span><b>Popularité :</b> ${pct(b.support,0)}</span><span><b>Déposé :</b> ${esc(b.created)}</span></div></div>${statusTag(b.status)}</div>${b.status!=='Rejeté'&&b.status!=='Retiré'?`<div class="law-stage">${['Rédaction','Assemblée','Seconde lecture','Promulgation'].map((x,i)=>`<div class="stage ${i<stage?'complete':i===stage?'current':''}"><div class="stage-num">${i<stage?'✓':i+1}</div><small>${x}</small></div>`).join('')}</div>`:''}${b.voteHistory?.length?`<div class="small-note">${b.voteHistory.map(v=>`${esc(v.chamber)} : ${v.yes} pour · ${v.no} contre`).join(' | ')}</div>`:''}<div class="bill-actions">${actions.join('')}<button class="button button-secondary button-sm" data-action="delete-bill" data-id="${b.id}">Supprimer</button></div></article>`;}
function pageParliament(){const s=app.state;const blocks=s.political.seatBlocks;const total=blocks.reduce((n,b)=>n+b.seats,0)||1;const threshold=s.parliament.majorityThreshold;const maj=blocks.filter(b=>['majority','moderate'].includes(b.id)).reduce((n,b)=>n+b.seats,0);return `${sectionHead('Parlement','Rapports de force, sessions et votes. La majorité peut être ajustée pour simuler une recomposition politique.',`<button class="button button-secondary" data-action="edit-seats">Modifier les sièges</button><button class="button button-primary" data-action="simulate-confidence">Test de confiance</button>`)}<div class="grid grid-3">${metric('SIÈGES',integer(s.parliament.totalSeats),'chambre principale','▥')}${metric('SEUIL DE MAJORITÉ',integer(threshold),'sièges nécessaires','⌁')}${metric('SOUTIEN ESTIMÉ',integer(maj),pct(maj/total*100),'◎',maj>=threshold?'majorité':'minorité')}</div><div class="grid grid-2 mt-12">${card(`Composition de ${esc(s.country.parliament)}`,'Répartition simulée des groupes politiques',`<div class="seat-bar">${blocks.map(b=>`<span class="seat-segment" style="width:${b.seats/total*100}%;background:${b.color}" title="${esc(b.name)} : ${b.seats}"></span>`).join('')}</div><div class="seat-legend">${blocks.map(b=>`<div class="seat-legend-item"><span class="seat-square" style="background:${b.color}"></span><span>${esc(b.name)}</span><strong>${integer(b.seats)}</strong></div>`).join('')}</div><div class="divider"></div><div class="stat-row"><span class="stat-row-label">Majorité absolue requise</span><span class="stat-row-value">${threshold} sièges</span></div><div class="stat-row mt-12"><span class="stat-row-label">Mandat / prochaine échéance</span><span class="stat-row-value">${esc(s.political.electionDate)}</span></div>`)}${card('Activité parlementaire','Textes et résultats de séance',`${s.parliament.lastVote?`<div class="notice"><span class="notice-icon">§</span><div><strong>Dernier vote : ${esc(s.parliament.lastVote.title)}</strong><p>${esc(s.parliament.lastVote.result)} · ${esc(s.parliament.lastVote.date)}</p></div></div><div class="divider"></div>`:''}<div class="stat-list"><div class="stat-row"><span class="stat-row-label">Textes déposés</span><span class="stat-row-value">${s.bills.length}</span></div><div class="stat-row"><span class="stat-row-label">En cours d’examen</span><span class="stat-row-value">${s.bills.filter(b=>['En lecture','Seconde lecture','À signer'].includes(b.status)).length}</span></div><div class="stat-row"><span class="stat-row-label">Promulgués</span><span class="stat-row-value">${s.bills.filter(b=>b.status==='Promulgué').length}</span></div><div class="stat-row"><span class="stat-row-label">Session</span><span class="stat-row-value">${esc(s.parliament.session)}</span></div></div><div class="divider"></div><button class="button button-secondary" data-page="bills">Ouvrir le registre législatif ↗</button>`)} </div><div class="section-heading"><div><h2>Textes en discussion</h2><p>Ouvrez les dossiers actifs pour les soumettre aux votes.</p></div></div>${s.bills.filter(b=>['En lecture','Seconde lecture','À signer'].includes(b.status)).length?s.bills.filter(b=>['En lecture','Seconde lecture','À signer'].includes(b.status)).map(b=>billCard(b)).join(''):emptyState('Aucun texte en discussion','Déposez un projet de loi pour lancer une procédure parlementaire.')}`;}
function pageElections(){
 const s=app.state,p=s.political,total=s.parliament.totalSeats||1;
 const incumbent=Math.max(0,Math.min(100,p.polling?.incumbent??p.approval));
 const opposition=Math.max(0,Math.min(100,p.polling?.opposition??(100-incumbent)));
 const undecided=Math.max(0,100-incumbent-opposition);
 const daysLeft=Math.ceil((new Date(p.electionDate+'T12:00:00')-new Date(`${s.date.year}-${String(s.date.month).padStart(2,'0')}-${String(s.date.day).padStart(2,'0')}T12:00:00`))/86400000);
 const partyName=p.ruling||'Majorité présidentielle';
 return `${sectionHead('Élections, campagne et opinion','Suivez les sondages, gérez les ressources de campagne, engagez des actions publiques et organisez un scrutin.',`<button class="button button-secondary" data-action="campaign-fund">Alimenter le budget de campagne</button><button class="button button-primary" data-action="simulate-election">Organiser un scrutin</button>`)}
 <div class="grid grid-4">${metric('INTENTIONS DE VOTE',pct(incumbent,0),'liste / candidat de la majorité','◉',incumbent>=50?'majorité en tête':'minorité en tête')}${metric('OPPOSITION',pct(opposition,0),'principale opposition cumulée','⇄')}${metric('BUDGET DE CAMPAGNE',billion(p.campaignFund),'ressources disponibles','▤')}${metric('ÉCHÉANCE ÉLECTORALE',daysLeft<0?`${Math.abs(daysLeft)} j de retard`:`${integer(daysLeft)} jours`,'avant le scrutin prévu','◷')}</div>
 <div class="grid grid-2 mt-12"><div class="stack">${card('Baromètre politique','Intentions de vote estimées',`<div class="stat-row"><span class="stat-row-label">${esc(partyName)}</span><span class="stat-row-value">${pct(incumbent,1)}</span></div><div class="progress-track mt-12"><div class="progress-fill" style="width:${incumbent}%"></div></div><div class="stat-row mt-12"><span class="stat-row-label">Opposition réunie</span><span class="stat-row-value">${pct(opposition,1)}</span></div><div class="progress-track mt-12"><div class="progress-fill red" style="width:${opposition}%"></div></div><div class="stat-row mt-12"><span class="stat-row-label">Indécis</span><span class="stat-row-value">${pct(undecided,1)}</span></div><div class="progress-track mt-12"><div class="progress-fill amber" style="width:${undecided}%"></div></div><div class="divider"></div><div class="two-col-stat"><div class="mini-stat"><small>Popularité présidentielle</small><strong>${pct(p.approval,0)}</strong><span>baromètre général</span></div><div class="mini-stat"><small>Confiance institutionnelle</small><strong>${pct(p.stability,0)}</strong><span>stabilité de l’exécutif</span></div></div><p class="small-note mt-12">Les intentions de vote partent de l’approbation présidentielle et évoluent selon les actions de campagne. Elles sont uniquement des valeurs de jeu.</p>`)}${card('Actions de campagne','Lancez une action pour faire évoluer le sondage.',`<div class="list-row"><div class="list-icon">⌂</div><div class="list-content"><div class="list-title">Déplacement national</div><div class="list-desc">Rencontres publiques et déplacements dans les régions.</div><div class="list-meta">Coût : 1,2 Md · effet indicatif : +1,4 pt</div></div><button class="button button-secondary button-sm" data-action="campaign-action" data-value="tour">Lancer</button></div><div class="list-row"><div class="list-icon">▤</div><div class="list-content"><div class="list-title">Présentation du programme</div><div class="list-desc">Détailler les priorités et engagements du mandat.</div><div class="list-meta">Coût : 0,7 Md · effet indicatif : +1,0 pt</div></div><button class="button button-secondary button-sm" data-action="campaign-action" data-value="program">Lancer</button></div><div class="list-row"><div class="list-icon">◉</div><div class="list-content"><div class="list-title">Débat télévisé</div><div class="list-desc">Intervention publique avec une exposition médiatique importante.</div><div class="list-meta">Coût : 0,4 Md · effet indicatif : ±0,7 pt</div></div><button class="button button-secondary button-sm" data-action="campaign-action" data-value="debate">Lancer</button></div><div class="list-row"><div class="list-icon">▧</div><div class="list-content"><div class="list-title">Campagne de terrain</div><div class="list-desc">Mobilisation des équipes, permanences et porte-à-porte.</div><div class="list-meta">Coût : 0,8 Md · effet indicatif : +0,8 pt</div></div><button class="button button-secondary button-sm" data-action="campaign-action" data-value="field">Lancer</button></div>` )}</div><div class="stack">${card('Calendrier électoral','Échéance prévue et résultats du dernier scrutin',`<div class="mini-stat"><small>DATE PRÉVUE DU SCRUTIN</small><strong>${esc(p.electionDate)}</strong><span>${daysLeft>=0?`J−${daysLeft}`:`Échéance dépassée de ${Math.abs(daysLeft)} jours`}</span></div><div class="divider"></div><div class="stat-row"><span class="stat-row-label">Mandat en cours</span><span class="stat-row-value">${esc(p.term)}</span></div><div class="stat-row mt-12"><span class="stat-row-label">Début de mandat</span><span class="stat-row-value">${p.mandateStartYear}</span></div><div class="stat-row mt-12"><span class="stat-row-label">Groupe au pouvoir</span><span class="stat-row-value">${esc(p.ruling)}</span></div><div class="bill-actions"><button class="button button-secondary button-sm" data-action="set-date">Modifier la date de simulation</button></div>${p.lastElection?`<div class="divider"></div><div class="notice"><span class="notice-icon">◉</span><div><strong>${esc(p.lastElection.winner)}</strong><p>${esc(p.lastElection.result)} · ${esc(p.lastElection.date)}</p></div></div>`:''}`)}${card('Financement politique','Ressources affectées à la campagne',`<div class="stat-row"><span class="stat-row-label">Fonds disponibles</span><span class="stat-row-value">${billion(p.campaignFund)}</span></div><div class="progress-track mt-12"><div class="progress-fill green" style="width:${Math.min(100,p.campaignFund/15*100)}%"></div></div><p class="small-note mt-12">Les dépenses d’action sont déduites de cette enveloppe. Le transfert de fonds réduit la trésorerie disponible du Trésor dans cette simulation.</p><button class="button button-primary button-sm mt-12" data-action="campaign-fund">Transférer des fonds</button>`)}${card('Dernière activité électorale','Actions et résultats consignés au journal',`<div class="timeline">${s.events.filter(e=>/campagne|scrutin|élection|vote|sondage/i.test(e.title+' '+e.type)).slice(0,5).map(e=>`<div class="timeline-item"><span class="timeline-marker"></span><div class="timeline-date">${esc(e.date)}</div><div class="timeline-title">${esc(e.title)}</div><div class="timeline-desc">${esc(e.description)}</div></div>`).join('')||`<div class="small-note">Aucune action électorale récente. Les actions menées apparaîtront dans ce journal.</div>`}</div>`)}</div></div>`;
}

function pageProjects(){const s=app.state;const total=s.projects.reduce((n,p)=>n+p.budget,0);const spent=s.projects.reduce((n,p)=>n+p.spent,0);return `${sectionHead('Plan d’investissement national','Créez des projets, suivez leurs coûts et leur avancement, suspendez-les ou terminez-les.',`<button class="button button-secondary" data-action="export-projects">Exporter le portefeuille</button><button class="button button-primary" data-action="new-project">+ Nouveau projet</button>`)}<div class="grid grid-4">${metric('PROJETS ACTIFS',integer(s.projects.filter(p=>p.status==='En cours').length),'portefeuille en cours','⌂')}${metric('ENGAGEMENT TOTAL',billion(total),'coût prévu au lancement','▤')}${metric('DÉPENSES ENGAGÉES',billion(spent),'crédits consommés','↗')}${metric('AVANCEMENT MOYEN',pct(s.projects.length?s.projects.reduce((n,p)=>n+p.progress,0)/s.projects.length:0),'moyenne non pondérée','◷')}</div><div class="grid grid-2 mt-12">${s.projects.length?s.projects.map(p=>`<section class="card"><div class="card-header"><div><h3 class="card-title">${esc(p.title)}</h3><div class="card-subtitle">${esc(p.sector)} · Priorité ${esc(p.priority.toLowerCase())}</div></div>${statusTag(p.status)}</div><div class="card-body"><div class="stat-row"><span class="stat-row-label">Avancement physique</span><span class="stat-row-value">${pct(p.progress,0)}</span></div><div class="progress-track mt-12"><div class="progress-fill ${p.progress>=100?'green':''}" style="width:${Math.min(100,p.progress)}%"></div></div><div class="two-col-stat mt-12"><div class="mini-stat"><small>Budget initial</small><strong>${billion(p.budget)}</strong><span>enveloppe approuvée</span></div><div class="mini-stat"><small>Dépenses engagées</small><strong>${billion(p.spent)}</strong><span>${pct(p.budget?p.spent/p.budget*100:0)} du budget</span></div></div><div class="list-desc mt-12">${esc(p.impact)}</div><div class="bill-actions"><button class="button button-secondary button-sm" data-action="edit-project" data-id="${p.id}">Modifier le projet</button>${p.status==='En cours'?`<button class="button button-secondary button-sm" data-action="suspend-project" data-id="${p.id}">Suspendre</button>`:p.status==='Suspendu'?`<button class="button button-secondary button-sm" data-action="resume-project" data-id="${p.id}">Reprendre</button>`:''}<button class="button button-secondary button-sm" data-action="delete-project" data-id="${p.id}">Supprimer</button></div></div></section>`).join(''):emptyState('Aucun projet créé','Lancez un chantier ou un programme public pour structurer votre mandat.',`<button class="button button-primary" data-action="new-project">Créer un projet</button>`)}</div>`;}
function pageProcurement(){
 const s=app.state,active=s.procurement.orders.filter(o=>o.status==='Commandé').length,spent=s.procurement.orders.filter(o=>o.status!=='Annulée').reduce((n,o)=>n+o.cost,0);
 const stockCount=Object.values(s.procurement.stock).reduce((n,v)=>n+v,0);
 const products=PROCUREMENT_CATALOG.map(item=>`<section class="card"><div class="card-body"><div class="list-row" style="padding-top:0;border:0"><div class="list-icon">▣</div><div class="list-content"><div class="list-title">${esc(item.name)}</div><div class="list-desc">${esc(item.description)}</div><div class="list-meta">Fournisseur : ${esc(item.supplier)} · Délai indicatif : ${item.delivery} jours</div></div></div><div class="two-col-stat mt-12"><div class="mini-stat"><small>Prix par lot</small><strong>${billion(item.unitPrice,2)}</strong><span>${esc(item.category)}</span></div><div class="mini-stat"><small>Stock disponible</small><strong>${integer(s.procurement.stock[item.id]||0)}</strong><span>lots déjà livrés</span></div></div><div class="bill-actions"><button class="button button-primary button-sm" data-action="purchase-item" data-id="${item.id}">Commander / acheter</button></div></div></section>`).join('');
 const orders=s.procurement.orders.length?s.procurement.orders.map(o=>`<tr><td><div class="table-strong">${esc(o.itemName)}</div><div class="table-muted">${esc(o.supplier)} · commande #${esc(o.number)}</div></td><td class="numeric">${integer(o.quantity)}</td><td class="numeric">${billion(o.cost,2)}</td><td>${o.status==='Commandé'?`${integer(o.daysLeft)} jours`:esc(o.status)}</td><td>${statusTag(o.status)}</td><td>${o.status==='Commandé'?`<button class="button button-secondary button-sm" data-action="cancel-order" data-id="${o.id}">Annuler</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6">${emptyState('Aucune commande','Les commandes et livraisons apparaîtront ici.')}</td></tr>`;
 return `${sectionHead('Achats publics et commandes','Achetez des fournitures, gérez les stocks et suivez les commandes jusqu’à leur livraison. Les achats sont payés depuis la trésorerie disponible.',`<button class="button button-secondary" data-action="export-orders">Exporter les commandes</button>`)}<div class="grid grid-4">${metric('COMMANDES EN COURS',integer(active),'livraisons attendues','◷')}${metric('LOTS EN STOCK',integer(stockCount),'toutes catégories','▣')}${metric('ACHATS CUMULÉS',billion(spent,2),'dépenses de commandes enregistrées','▤')}${metric('TRÉSORERIE',billion(s.finance.cash),'disponible pour financer les achats','€')}</div>${sectionHead('Catalogue d’approvisionnement','Choisissez une catégorie, le nombre de lots et le fournisseur proposé. Le coût total est calculé avant validation.')}
 <div class="grid grid-2">${products}</div><div class="section-heading"><div><h2>Commandes & livraisons</h2><p>Le temps de livraison diminue au fil des jours simulés.</p></div></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Article / fournisseur</th><th>Lots</th><th>Coût total</th><th>Livraison</th><th>Statut</th><th></th></tr></thead><tbody>${orders}</tbody></table></div><div class="card-footer"><span class="small-note">Les stocks ne sont crédités qu’à la livraison de la commande.</span><button class="button button-secondary button-sm" data-action="advance-day">Faire avancer d’un jour</button></div></section>`;
}

function pageCabinet(){const s=app.state;return `${sectionHead('Équipe gouvernementale','Modifiez l’équipe exécutive, affectez les portefeuilles et suivez la confiance de chaque ministre.',`<button class="button button-primary" data-action="new-minister">+ Nommer un ministre</button>`)}<div class="grid grid-3">${metric('MEMBRES DU CABINET',integer(s.cabinet.length),'équipe exécutive','♙')}${metric('CONFIANCE MOYENNE',pct(s.cabinet.reduce((n,m)=>n+m.confidence,0)/Math.max(1,s.cabinet.length),0),'indice interne','◎')}${metric('STABILITÉ POLITIQUE',pct(s.political.stability,0),'cohésion institutionnelle','▥')}</div><div class="grid grid-2 mt-12">${s.cabinet.map(m=>`<section class="card"><div class="card-body"><div class="list-row" style="padding-top:0;border:0"><div class="list-icon" style="height:42px;width:42px;font-size:17px">♙</div><div class="list-content"><div class="list-title">${esc(m.name)}</div><div class="list-desc">${esc(m.role)}</div><div class="list-meta">${esc(m.party)}</div></div><button class="button button-secondary button-sm" data-action="edit-minister" data-id="${m.id}">Modifier</button></div><div class="divider"></div><div class="stat-row"><span class="stat-row-label">Portefeuille</span><span class="stat-row-value">${esc(m.ministry)}</span></div><div class="stat-row mt-12"><span class="stat-row-label">Indice de confiance</span><span class="stat-row-value">${pct(m.confidence,0)}</span></div><div class="progress-track mt-12"><div class="progress-fill ${m.confidence>=65?'green':'amber'}" style="width:${m.confidence}%"></div></div><div class="bill-actions"><button class="button button-secondary button-sm" data-action="dismiss-minister" data-id="${m.id}">Révoquer</button></div></div></section>`).join('')}</div>`;}
function pageDefense(){const s=app.state;return `${sectionHead('Carte et suivi des unités','Sélectionnez une unité puis cliquez sur la carte pour lui assigner une destination. L’avancement du déplacement est simulé au fil des jours.',`<button class="button button-secondary" data-action="reset-unit-positions">Réinitialiser les positions</button><button class="button button-primary" data-action="new-unit">+ Ajouter une unité</button>`)}<div class="map-layout"><section class="card map-card"><div class="map-toolbar"><div class="map-toolbar-left"><span class="tag tag-blue">CARTE MONDIALE</span><span class="map-hint">Cliquez sur une unité puis sur la carte pour définir sa destination.</span></div><div class="map-toolbar-right"><span class="map-legend"><i class="map-key friendly"></i> Forces</span><span class="map-legend"><i class="map-key mission"></i> En déplacement</span><span class="map-legend"><i class="map-key alert"></i> Alerte</span></div></div><div id="worldMap" class="leaflet-map" role="application" aria-label="Carte mondiale interactive"></div><div class="card-footer"><span class="small-note" id="mapStatus">Chargement de la carte…</span><div class="section-actions"><button class="button button-secondary button-sm" data-action="map-home">Vue nationale</button><button class="button button-secondary button-sm" data-action="map-world">Vue mondiale</button></div></div></section><div class="stack">${card('Ordre de bataille','Unités suivies sur la carte',`<div class="stat-row mb-12"><span class="stat-row-label">Unités enregistrées</span><span class="stat-row-value">${s.defense.units.length}</span></div><div class="stat-row mb-12"><span class="stat-row-label">Personnel / effectifs agrégés</span><span class="stat-row-value">${integer(s.defense.units.reduce((n,u)=>n+u.strength,0))}</span></div><div class="divider"></div><div id="unitList">${renderUnitList()}</div>`)}${card('Ordre sélectionné','Commandes de déplacement',`<div id="selectedUnitPanel">${renderSelectedUnit()}</div><div class="divider"></div><div class="field"><label for="alertLevel">Niveau d’alerte national</label><select id="alertLevel" name="alertLevel"><option ${s.defense.alertLevel==='Normal'?'selected':''}>Normal</option><option ${s.defense.alertLevel==='Renforcé'?'selected':''}>Renforcé</option><option ${s.defense.alertLevel==='Maximum'?'selected':''}>Maximum</option></select></div><button class="button button-secondary button-sm mt-12" data-action="apply-alert-level">Appliquer le niveau d’alerte</button>`)}<div class="callout-blue"><strong>Portée de la simulation</strong>Cette carte représente des positions de jeu modifiables et des unités fictives. Les déplacements sont abstraits et ne constituent pas des informations opérationnelles réelles.</div></div></div>`;}
function renderUnitList(){const s=app.state;return s.defense.units.length?s.defense.units.map(u=>`<div class="unit-list-item ${s.defense.selectedUnitId===u.id?'selected':''}" data-action="select-unit" data-id="${u.id}"><div class="unit-list-top"><div class="unit-list-name">${esc(u.name)}</div>${statusTag(u.destination?'En manœuvre':u.status)}</div><div class="unit-list-sub">${({HQ:'Commandement',ARM:'Forces terrestres',AIR:'Forces aériennes',NAV:'Forces navales',LOG:'Logistique'})[u.type]||esc(u.type)} · ${integer(u.strength)} effectifs</div><div class="unit-list-coord">${Number(u.lat).toFixed(3)}, ${Number(u.lng).toFixed(3)} · disponibilité ${pct(u.readiness,0)}</div></div>`).join(''):emptyState('Aucune unité','Ajoutez une unité pour l’afficher sur la carte.',`<button class="button button-primary button-sm" data-action="new-unit">Ajouter une unité</button>`);}
function renderSelectedUnit(){const s=app.state,u=s.defense.units.find(x=>x.id===s.defense.selectedUnitId);if(!u)return emptyState('Aucune unité sélectionnée','Sélectionnez une unité dans la liste.');return `<div class="list-title">${esc(u.name)}</div><div class="list-desc">${esc(({HQ:'Commandement',ARM:'Forces terrestres',AIR:'Forces aériennes',NAV:'Forces navales',LOG:'Logistique'})[u.type]||u.type)}</div><div class="two-col-stat mt-12"><div class="mini-stat"><small>Effectifs</small><strong>${integer(u.strength)}</strong></div><div class="mini-stat"><small>Disponibilité</small><strong>${pct(u.readiness,0)}</strong></div></div><div class="divider"></div><div class="stat-row"><span class="stat-row-label">Position actuelle</span><span class="stat-row-value">${Number(u.lat).toFixed(3)}, ${Number(u.lng).toFixed(3)}</span></div>${u.destination?`<div class="stat-row mt-12"><span class="stat-row-label">Destination</span><span class="stat-row-value">${u.destination.lat.toFixed(2)}, ${u.destination.lng.toFixed(2)}</span></div><div class="progress-track mt-12"><div class="progress-fill" style="width:${u.moveProgress||0}%"></div></div><button class="button button-secondary button-sm mt-12" data-action="cancel-move" data-id="${u.id}">Annuler le déplacement</button>`:`<p class="small-note mt-12">Aucune destination assignée. Cliquez sur la carte pour donner un ordre de déplacement.</p>`}<div class="bill-actions"><button class="button button-secondary button-sm" data-action="edit-unit" data-id="${u.id}">Modifier l’unité</button><button class="button button-secondary button-sm" data-action="delete-unit" data-id="${u.id}">Dissoudre</button></div>`;}
function pageDiplomacy(){
 const s=app.state;
 const partners=Object.entries(s.diplomacy.relations).sort((a,b)=>b[1]-a[1]);
 const partnerRows=partners.map(([name,rel])=>`<div class="stat-row"><span class="stat-row-label">${esc(name)}</span><span class="stat-row-value">${rel}/100</span></div><div class="progress-track mt-12" style="margin-bottom:13px"><div class="progress-fill ${rel>=70?'green':rel>=50?'':'red'}" style="width:${rel}%"></div></div>`).join('');
 const deals=s.diplomacy.deals.length?s.diplomacy.deals.map(d=>`<div class="deal-card"><div class="deal-top"><div><div class="deal-country">${esc(d.partner)}</div><div class="list-desc">${esc(d.type)} · ${esc(d.product)}</div></div>${statusTag(d.status)}</div><p>${esc(d.summary||'Accord bilatéral conclu dans le cadre de la simulation.')}</p><div class="deal-numbers"><span>Valeur : ${billion(d.value)}</span><span>Tarif : ${pct(d.tariff)}</span></div><div class="bill-actions">${d.status==='En négociation'?`<button class="button button-primary button-sm" data-action="sign-deal" data-id="${d.id}">Signer l’accord</button>`:''}<button class="button button-secondary button-sm" data-action="delete-deal" data-id="${d.id}">Clôturer</button></div></div>`).join(''):emptyState('Aucun accord enregistré','Ouvrez une négociation commerciale ou diplomatique pour établir un accord.',`<button class="button button-primary button-sm" data-action="new-deal">Commencer une négociation</button>`);
 const partnerCard=card('Partenaires diplomatiques','Indice de relation simulé sur 100',partnerRows);
 const toolsCard=card('Instruments diplomatiques','Vos leviers de politique étrangère',`<div class="stat-row"><span class="stat-row-label">Droits de douane moyens</span><span class="stat-row-value">${pct(s.diplomacy.tariff)}</span></div><div class="stat-row mt-12"><span class="stat-row-label">Budget annuel d’aide extérieure</span><span class="stat-row-value">${billion(s.diplomacy.aidBudget)}</span></div><div class="bill-actions"><button class="button button-secondary button-sm" data-action="edit-aid">Modifier l’aide internationale</button></div>`);
 const dealsCard=card('Accords et traités','Historique des négociations',deals);
 const flowsCard=card('Commerce bilatéral','Vue abstraite des flux',`<div class="list-row"><div class="list-icon">↗</div><div class="list-content"><div class="list-title">Exportations</div><div class="list-desc">Les accords commerciaux augmentent progressivement la capacité d’échange simulée.</div></div><div class="numeric">${billion(s.economy.exports,0)}</div></div><div class="list-row"><div class="list-icon">↘</div><div class="list-content"><div class="list-title">Importations</div><div class="list-desc">Les droits de douane peuvent améliorer le solde à court terme, mais rendent les biens importés plus coûteux.</div></div><div class="numeric">${billion(s.economy.imports,0)}</div></div>`);
 return `${sectionHead('Relations extérieures et commerce','Négociez des accords, développez les échanges, ajustez les droits de douane et accordez une aide extérieure.',`<button class="button button-secondary" data-action="edit-tariffs">Droits de douane</button><button class="button button-primary" data-action="new-deal">+ Négocier un accord</button>`)}<div class="grid grid-4">${metric('EXPORTATIONS',billion(s.economy.exports,0),'annuelles estimées','↗')}${metric('IMPORTATIONS',billion(s.economy.imports,0),'annuelles estimées','↘')}${metric('SOLDE COMMERCIAL',`${s.economy.tradeBalance<0?'−':''}${billion(Math.abs(s.economy.tradeBalance),0)}`,'exportations moins importations','⇄',s.economy.tradeBalance>=0?'excédent':'déficit')}${metric('ACCORDS ACTIFS',integer(s.diplomacy.deals.filter(d=>d.status==='Signé').length),'accords bilatéraux','§')}</div><div class="grid grid-2 mt-12"><div class="stack">${partnerCard}${toolsCard}</div><div class="stack">${dealsCard}${flowsCard}</div></div>`;
}
function pageEvents(){const s=app.state;return `${sectionHead('Journal national','Historique chronologique des décisions, votes, événements et changements de politique.',`<button class="button button-secondary" data-action="export-events">Exporter le journal</button><button class="button button-primary" data-action="new-event">+ Ajouter une note</button>`)}${s.events.length?`<section class="card"><div class="card-body"><div class="timeline">${s.events.map(e=>`<div class="timeline-item"><span class="timeline-marker" style="${e.impact==='negative'?'background:#b65f5f':e.impact==='positive'?'background:#559278':''}"></span><div class="timeline-date">${esc(e.date)} · ${esc(e.type)}</div><div class="timeline-title">${esc(e.title)}</div><div class="timeline-desc">${esc(e.description)}</div></div>`).join('')}</div></div></section>`:emptyState('Le journal est vide','Les décisions futures seront enregistrées automatiquement.')}`;}
function pageSave(){const s=app.state;return `${sectionHead('Sauvegarde et options','Gérez les données de votre campagne, exportez le dossier complet ou restaurez une sauvegarde JSON.',`<button class="button button-primary" data-action="save-now">Enregistrer maintenant</button>`)}<div class="grid grid-2"><div class="stack">${card('Dossier de campagne','Une sauvegarde locale est conservée sur cet appareil.',`<div class="setting-row"><div><strong>Sauvegarde automatique</strong><p>Enregistrer chaque décision et chaque passage de journée dans le navigateur.</p></div><button class="switch ${s.settings.autoSave?'on':''}" data-action="toggle-autosave" aria-label="Activer la sauvegarde automatique"></button></div><div class="setting-row"><div><strong>Événements aléatoires</strong><p>Activer des événements politiques et économiques lors du passage du temps.</p></div><button class="switch ${s.settings.randomEvents?'on':''}" data-action="toggle-random" aria-label="Activer les événements aléatoires"></button></div><div class="setting-row"><div><strong>Stockage utilisé</strong><p id="storageUse">${integer(new Blob([JSON.stringify(s)]).size/1024)} Ko environ</p></div><span class="tag tag-green">Local</span></div><div class="divider"></div><div class="bill-actions"><button class="button button-primary" data-action="export-save">Télécharger la sauvegarde JSON</button><button class="button button-secondary" data-action="import-save">Importer un fichier JSON</button><input type="file" id="importFile" accept="application/json,.json" style="display:none"></div>`)}${card('Export des données','Les exports CSV sont utilisables dans un tableur.',`<div class="list-row"><div class="list-icon">▤</div><div class="list-content"><div class="list-title">Compte public</div><div class="list-desc">Export des recettes, dépenses, dette et trésorerie.</div></div><button class="button button-secondary button-sm" data-action="export-finance">CSV</button></div><div class="list-row"><div class="list-icon">§</div><div class="list-content"><div class="list-title">Registre des lois</div><div class="list-desc">Textes, statuts, coûts et résultats des votes.</div></div><button class="button button-secondary button-sm" data-action="export-bills">CSV</button></div><div class="list-row"><div class="list-icon">⌂</div><div class="list-content"><div class="list-title">Projets nationaux</div><div class="list-desc">Budgets et progression des investissements.</div></div><button class="button button-secondary button-sm" data-action="export-projects">CSV</button></div>`)}</div><div class="stack">${card('Règles de simulation','Configuration de la campagne',`<div class="setting-row"><div><strong>Pays en cours</strong><p>${esc(s.country.name)}</p></div><button class="button button-secondary button-sm" data-action="open-country">Changer</button></div><div class="setting-row"><div><strong>Date de simulation</strong><p>${dstr()}</p></div><button class="button button-secondary button-sm" data-action="set-date">Modifier</button></div><div class="setting-row"><div><strong>Avancer le temps</strong><p>Chaque jour fait évoluer les projets et rapproche les unités de leurs destinations.</p></div><button class="button button-primary button-sm" data-action="advance-month">+ 30 jours</button></div><div class="divider"></div><div class="danger-zone"><strong>Réinitialiser la campagne</strong><p>Cette action efface les décisions, les textes et les projets de la partie en cours. Exportez une sauvegarde avant de continuer.</p><button class="button button-danger button-sm" data-action="reset-campaign">Recommencer une campagne</button></div>`)}${card('À propos d’ATLAS NATIONS','Fichier autonome et modifiable',`<p class="form-intro">ATLAS NATIONS est une simulation de gouvernance locale. Les chiffres de départ et les résultats sont simulés, et ne constituent ni des prévisions officielles ni des données gouvernementales.</p><div class="stat-row"><span class="stat-row-label">Version</span><span class="stat-row-value">3.0.0</span></div><div class="stat-row mt-12"><span class="stat-row-label">Technologies</span><span class="stat-row-value">HTML · CSS · JavaScript</span></div><div class="stat-row mt-12"><span class="stat-row-label">Dépendance cartographique</span><span class="stat-row-value">Leaflet / OpenStreetMap</span></div><div class="stat-row mt-12"><span class="stat-row-label">Serveur requis</span><span class="tag tag-green">Non</span></div>`)}</div></div>`;}

function showModal(title,subtitle,body,footer=''){const host=document.getElementById('modalHost');host.innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button modal-close" data-action="close-modal" aria-label="Fermer">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;const f=host.querySelector('input,select,textarea,button');if(f)f.focus({preventScroll:true});}
function closeModal(){document.getElementById('modalHost').innerHTML='';}
function modalFooter(cancel='Annuler',ok='Enregistrer'){return `<button class="button button-secondary" type="button" data-action="close-modal">${cancel}</button><button class="button button-primary" type="submit" form="modalForm">${ok}</button>`;}
function openCountryModal(){showModal('Choisir le pays','Chaque pays dispose de paramètres de départ propres. La sélection démarre une nouvelle campagne.',`<div class="country-selector">${Object.entries(COUNTRIES).map(([key,c])=>`<button class="country-choice ${key===app.state.countryKey?'selected':''}" data-action="choose-country" data-value="${key}"><span class="flag">${c.flag}</span><span><strong>${esc(c.short)}</strong><small>PIB ${Math.round(c.gdp).toLocaleString('fr-FR')} Md</small></span></button>`).join('')}</div><p class="small-note mt-12">Changer de pays crée une nouvelle campagne. Exportez votre sauvegarde actuelle pour la conserver.</p>`);}
function openBillModal(id=null,sectorPreset=''){const s=app.state;const b=id?s.bills.find(x=>x.id===id):null;if(id&&!b)return;showModal(b?'Modifier le projet de loi':'Rédiger un projet de loi','Définissez l’objet du texte, ses conséquences estimées et son soutien public.',`<form id="modalForm" data-form="bill"><input type="hidden" name="id" value="${esc(b?.id||'')}"><div class="form-grid"><div class="field full"><label for="bill-title">Titre du texte</label><input id="bill-title" name="title" required maxlength="120" value="${esc(b?.title||'')}" placeholder="Ex. Loi de programmation des infrastructures"></div><div class="field"><label for="bill-sector">Domaine</label><select id="bill-sector" name="sector">${['Économie','Fiscalité','Santé','Éducation','Sécurité','Défense','Écologie','Transports','Logement','Justice','Agriculture','Institutions','Affaires étrangères','Autre'].map(v=>`<option ${((b?.sector||sectorPreset)===v)?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="bill-support">Soutien public estimé (%)</label><input id="bill-support" type="number" name="support" min="0" max="100" step="1" value="${b?.support??55}" required></div><div class="field"><label for="bill-cost">Coût annuel estimé (Md ${esc(s.country.currency)})</label><input id="bill-cost" type="number" name="cost" min="0" max="2000" step="0.1" value="${b?.cost??0}" required></div><div class="field"><label for="bill-revenue">Recette annuelle attendue (Md ${esc(s.country.currency)})</label><input id="bill-revenue" type="number" name="revenue" min="0" max="2000" step="0.1" value="${b?.revenue??0}" required></div><div class="field full"><label for="bill-summary">Résumé et objectifs</label><textarea id="bill-summary" name="summary" maxlength="800" required placeholder="Objectifs, publics concernés, principales mesures…">${esc(b?.summary||'')}</textarea></div></div></form>`,modalFooter('Annuler',b?'Enregistrer les modifications':'Enregistrer le brouillon'));}
function openProjectModal(id=null){const p=id?app.state.projects.find(x=>x.id===id):null;if(id&&!p)return;showModal(p?'Modifier le projet':'Créer un grand projet','Planifiez un investissement, un budget et une durée de réalisation.',`<form id="modalForm" data-form="project"><input type="hidden" name="id" value="${esc(p?.id||'')}"><div class="form-grid"><div class="field full"><label for="project-title">Nom du programme</label><input id="project-title" name="title" required maxlength="120" value="${esc(p?.title||'')}" placeholder="Ex. Programme national de logement"></div><div class="field"><label for="project-sector">Secteur</label><select id="project-sector" name="sector">${['Transports','Santé','Éducation','Énergie','Défense','Logement','Numérique','Agriculture','Recherche','Environnement','Autre'].map(v=>`<option ${(p?.sector||'Transports')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="project-priority">Priorité</label><select id="project-priority" name="priority">${['Haute','Normale','Basse'].map(v=>`<option ${(p?.priority||'Normale')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="project-budget">Budget total (Md ${esc(app.state.country.currency)})</label><input id="project-budget" name="budget" type="number" min="0.1" max="3000" step="0.1" value="${p?.budget??2}" required></div><div class="field"><label for="project-duration">Durée (jours de simulation)</label><input id="project-duration" name="duration" type="number" min="1" max="5000" step="1" value="${p?.duration??365}" required></div><div class="field"><label for="project-progress">Avancement actuel (%)</label><input id="project-progress" name="progress" type="number" min="0" max="100" step="1" value="${p?.progress??0}" required></div><div class="field"><label for="project-status">Statut</label><select id="project-status" name="status">${['En préparation','En cours','Suspendu','Terminé'].map(v=>`<option ${(p?.status||'En cours')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label for="project-impact">Impact attendu</label><textarea id="project-impact" name="impact" required maxlength="400">${esc(p?.impact||'Améliorer les services publics et soutenir l’activité économique.')}</textarea></div></div></form>`,modalFooter('Annuler',p?'Enregistrer':'Créer le projet'));}
function openBorrowModal(){showModal('Financer l’État','L’emprunt augmente la trésorerie et la dette publique. Les intérêts annuels sont ajoutés à la charge de la dette.',`<form id="modalForm" data-form="borrow"><div class="form-grid"><div class="field full"><label for="loan-label">Intitulé de l’emprunt</label><input id="loan-label" name="label" value="Émission obligataire souveraine" maxlength="100" required></div><div class="field"><label for="loan-principal">Capital levé (Md ${esc(app.state.country.currency)})</label><input id="loan-principal" name="principal" type="number" min="0.1" max="2000" step="0.1" value="25" required></div><div class="field"><label for="loan-rate">Taux annuel (%)</label><input id="loan-rate" name="rate" type="number" min="0.1" max="25" step="0.1" value="${app.state.finance.loanRate}" required></div><div class="field"><label for="loan-term">Durée (années)</label><select name="term" id="loan-term"><option value="2">2 ans</option><option value="5">5 ans</option><option value="10" selected>10 ans</option><option value="15">15 ans</option><option value="20">20 ans</option><option value="30">30 ans</option></select></div><div class="field"><label for="loan-use">Affectation</label><select id="loan-use" name="use"><option>Financement général du Trésor</option><option>Investissements publics</option><option>Urgence nationale</option><option>Refinancement de dette</option></select></div></div><div class="notice mt-12"><span class="notice-icon">i</span><div><strong>Avant de confirmer</strong><p>Les fonds arrivent immédiatement. Le principal est ajouté à la dette, et les intérêts augmentent le budget de la charge de la dette.</p></div></div></form>`,modalFooter('Annuler','Émettre l’emprunt'));}
function openUnitModal(id=null){const u=id?app.state.defense.units.find(x=>x.id===id):null;if(id&&!u)return;showModal(u?'Modifier l’unité':'Ajouter une unité','Gérez les éléments suivis dans votre carte de simulation.',`<form id="modalForm" data-form="unit"><input type="hidden" name="id" value="${esc(u?.id||'')}"><div class="form-grid"><div class="field full"><label for="unit-name">Nom de l’unité</label><input id="unit-name" name="name" maxlength="100" required value="${esc(u?.name||'')}" placeholder="Ex. Commandement de zone Sud"></div><div class="field"><label for="unit-type">Type</label><select id="unit-type" name="type">${[['HQ','Commandement'],['ARM','Forces terrestres'],['AIR','Forces aériennes'],['NAV','Forces navales'],['LOG','Logistique']].map(([v,l])=>`<option value="${v}" ${(u?.type||'ARM')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="unit-status">État</label><select id="unit-status" name="status">${['Opérationnel','En alerte','En manœuvre','Soutien','Patrouille'].map(v=>`<option ${(u?.status||'Opérationnel')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="unit-strength">Effectifs / éléments</label><input id="unit-strength" name="strength" type="number" min="1" max="500000" value="${u?.strength??1000}" required></div><div class="field"><label for="unit-readiness">Disponibilité (%)</label><input id="unit-readiness" name="readiness" type="number" min="0" max="100" value="${u?.readiness??80}" required></div><div class="field"><label for="unit-lat">Latitude</label><input id="unit-lat" name="lat" type="number" min="-85" max="85" step="0.001" value="${u?.lat??app.state.country.location[0]}" required></div><div class="field"><label for="unit-lng">Longitude</label><input id="unit-lng" name="lng" type="number" min="-180" max="180" step="0.001" value="${u?.lng??app.state.country.location[1]}" required></div></div></form>`,modalFooter('Annuler',u?'Enregistrer':'Ajouter l’unité'));}
function openPurchaseModal(itemId){const item=PROCUREMENT_CATALOG.find(x=>x.id===itemId);if(!item)return;showModal('Commander des fournitures',item.name,`<form id="modalForm" data-form="purchase"><input type="hidden" name="itemId" value="${esc(item.id)}"><div class="notice"><span class="notice-icon">▣</span><div><strong>${esc(item.supplier)}</strong><p>${esc(item.description)} Délai indicatif : ${item.delivery} jours.</p></div></div><div class="form-grid mt-12"><div class="field"><label for="purchase-quantity">Nombre de lots</label><input id="purchase-quantity" name="quantity" type="number" min="1" max="200" value="1" required></div><div class="field"><label for="purchase-supplier">Fournisseur</label><input id="purchase-supplier" name="supplier" maxlength="100" value="${esc(item.supplier)}" required></div><div class="field full"><label for="purchase-note">Objet / référence</label><input id="purchase-note" name="note" maxlength="140" placeholder="Référence budgétaire ou justification"></div></div><div class="two-col-stat mt-12"><div class="mini-stat"><small>Prix unitaire par lot</small><strong>${billion(item.unitPrice,2)}</strong></div><div class="mini-stat"><small>Trésorerie disponible</small><strong>${billion(app.state.finance.cash)}</strong></div></div><p class="small-note mt-12">Le montant total sera contrôlé au moment de confirmer la commande. Les lots seront ajoutés au stock à la date de livraison.</p></form>`,modalFooter('Annuler','Valider la commande'));}

function openDealModal(){const partners=Object.keys(app.state.diplomacy.relations);showModal('Nouvelle négociation','Définissez les paramètres d’un accord commercial ou diplomatique bilatéral.',`<form id="modalForm" data-form="deal"><div class="form-grid"><div class="field"><label for="deal-partner">Partenaire</label><select name="partner" id="deal-partner">${partners.map(p=>`<option>${esc(p)}</option>`).join('')}<option>Autre partenaire</option></select></div><div class="field"><label for="deal-type">Type d’accord</label><select id="deal-type" name="type"><option>Accord commercial</option><option>Accord de coopération</option><option>Accord énergétique</option><option>Accord de défense</option><option>Partenariat scientifique</option><option>Accord de libre-échange</option></select></div><div class="field"><label for="deal-product">Secteur concerné</label><select id="deal-product" name="product"><option>Échanges généraux</option><option>Énergie</option><option>Agriculture</option><option>Industrie</option><option>Technologies</option><option>Défense</option><option>Recherche</option><option>Services</option></select></div><div class="field"><label for="deal-value">Valeur annuelle estimée (Md)</label><input id="deal-value" name="value" type="number" min="0" max="1000" step="0.1" value="4" required></div><div class="field"><label for="deal-tariff">Droit de douane appliqué (%)</label><input id="deal-tariff" name="tariff" type="number" min="0" max="80" step="0.1" value="${app.state.diplomacy.tariff}" required></div><div class="field full"><label for="deal-summary">Objectifs de la négociation</label><textarea id="deal-summary" name="summary" maxlength="400" required>Faciliter les échanges et renforcer les relations bilatérales.</textarea></div></div></form>`,modalFooter('Annuler','Ouvrir la négociation'));}
function openSocietyModal(){const x=app.state.society;showModal('Modifier les indicateurs nationaux','Les modifications sont des hypothèses de scénario pour la simulation.',`<form id="modalForm" data-form="society"><div class="form-grid">${[['population','Population (millions)',x.population,.1,2000,.1],['unemployment','Chômage (%)',x.unemployment,0,50,.1],['inflation','Inflation (%)',x.inflation,-10,100,.1],['growth','Croissance annuelle (%)',x.growth,-30,30,.1],['inequality','Inégalités (indice / 100)',x.inequality,0,100,1],['poverty','Pauvreté (%)',x.poverty,0,100,.1],['lifeExpectancy','Espérance de vie (années)',x.lifeExpectancy,30,110,.1],['renewables','Part renouvelable (%)',x.renewables,0,100,.1],['education','Accès à l’éducation (%)',x.education,0,100,.1],['health','Accès aux soins (%)',x.health,0,100,.1],['migration','Migration nette (% / an)',x.migration,-10,10,.01],['crime','Indice de sécurité (sur 100)',x.crime,0,100,1]].map(([id,label,v,min,max,step])=>`<div class="field"><label for="soc-${id}">${label}</label><input type="number" id="soc-${id}" name="${id}" min="${min}" max="${max}" step="${step}" value="${v}" required></div>`).join('')}</div></form>`,modalFooter('Annuler','Appliquer'));}
function openMinistryModal(id){const m=app.state.finance.ministries.find(x=>x.id===id);if(!m)return;showModal('Modifier un crédit budgétaire',m.name,`<form id="modalForm" data-form="ministry"><input type="hidden" name="id" value="${m.id}"><div class="field"><label for="min-budget">Crédit annuel (Md ${esc(app.state.country.currency)})</label><input id="min-budget" type="number" name="budget" min="0" max="3000" step="0.1" value="${m.budget}" required></div><p class="small-note mt-12">Le changement modifie immédiatement le montant des dépenses publiques et le solde annuel.</p></form>`,modalFooter('Annuler','Modifier le crédit'));}
function openAllBudgetModal(){showModal('Réviser le budget de l’État','Les montants sont exprimés en milliards par an.',`<form id="modalForm" data-form="all-budget"><div class="form-grid">${app.state.finance.ministries.map(m=>`<div class="field"><label for="budget-${m.id}">${esc(m.abbr)}</label><input id="budget-${m.id}" type="number" name="${m.id}" min="0" max="3000" step="0.1" value="${m.budget}" required></div>`).join('')}</div></form>`,modalFooter('Annuler','Valider le budget'));}
function openMinisterModal(id=null){const m=id?app.state.cabinet.find(x=>x.id===id):null;if(id&&!m)return;showModal(m?'Modifier un membre du gouvernement':'Nommer un ministre','L’équipe gouvernementale peut être entièrement adaptée à votre scénario.',`<form id="modalForm" data-form="minister"><input type="hidden" name="id" value="${esc(m?.id||'')}"><div class="form-grid"><div class="field full"><label for="minister-name">Nom complet</label><input id="minister-name" name="name" required maxlength="80" value="${esc(m?.name||'')}"></div><div class="field"><label for="minister-role">Fonction</label><input id="minister-role" name="role" required maxlength="100" value="${esc(m?.role||'Ministre délégué')}"></div><div class="field"><label for="minister-ministry">Portefeuille</label><input id="minister-ministry" name="ministry" required maxlength="100" value="${esc(m?.ministry||'Nouveau portefeuille')}"></div><div class="field"><label for="minister-party">Parti / groupe</label><input id="minister-party" name="party" required maxlength="80" value="${esc(m?.party||app.state.political.ruling)}"></div><div class="field"><label for="minister-confidence">Confiance interne (%)</label><input id="minister-confidence" name="confidence" type="number" min="0" max="100" value="${m?.confidence??60}" required></div></div></form>`,modalFooter('Annuler',m?'Enregistrer':'Nommer'));}
function openSeatModal(){showModal('Modifier les rapports de force','Ajustez le nombre de sièges de chaque groupe. Le total devient celui que vous définissez.',`<form id="modalForm" data-form="seats"><div class="form-grid">${app.state.political.seatBlocks.map(b=>`<div class="field"><label for="seat-${b.id}">${esc(b.name)}</label><input id="seat-${b.id}" name="${b.id}" type="number" min="0" max="2000" value="${b.seats}" required></div>`).join('')}</div><p class="small-note mt-12">Le total de sièges sera recalculé automatiquement.</p></form>`,modalFooter('Annuler','Mettre à jour'));}
function openTariffModal(){showModal('Droits de douane','Le taux moyen influence les prix à l’importation et les recettes commerciales simulées.',`<form id="modalForm" data-form="tariff"><div class="field"><label for="tariff">Taux moyen (%)</label><input id="tariff" name="tariff" type="number" min="0" max="80" step="0.1" value="${app.state.diplomacy.tariff}" required></div></form>`,modalFooter('Annuler','Appliquer'));}
function openAidModal(){showModal('Aide internationale','Définissez une enveloppe annuelle d’aide publique au développement.',`<form id="modalForm" data-form="aid"><div class="field"><label for="aid-budget">Budget annuel (Md ${esc(app.state.country.currency)})</label><input id="aid-budget" name="budget" type="number" min="0" max="500" step="0.1" value="${app.state.diplomacy.aidBudget}" required></div></form>`,modalFooter('Annuler','Appliquer'));}
function openCampaignFundModal(){showModal('Transférer des fonds vers la campagne','Le transfert provient de la trésorerie publique dans ce modèle de scénario et est enregistré comme mouvement financier.',`<form id="modalForm" data-form="campaign-fund"><div class="field"><label for="campaign-amount">Montant à transférer (Md ${esc(app.state.country.currency)})</label><input id="campaign-amount" name="amount" type="number" min="0.1" max="100" step="0.1" value="2" required></div><div class="two-col-stat mt-12"><div class="mini-stat"><small>Trésorerie disponible</small><strong>${billion(app.state.finance.cash)}</strong></div><div class="mini-stat"><small>Budget de campagne actuel</small><strong>${billion(app.state.political.campaignFund)}</strong></div></div><p class="small-note mt-12">Cette mécanique finance le gameplay. Elle ne représente pas les règles réelles de financement des campagnes électorales.</p></form>`,modalFooter('Annuler','Transférer les fonds'));}

function openEventModal(){showModal('Ajouter une note au journal','Utilisez cette fonction pour consigner une décision ou un événement de votre scénario.',`<form id="modalForm" data-form="event"><div class="form-grid"><div class="field full"><label for="event-title">Titre</label><input id="event-title" name="title" maxlength="120" required></div><div class="field"><label for="event-type">Catégorie</label><select id="event-type" name="type"><option>Décision</option><option>Institution</option><option>Économie</option><option>Diplomatie</option><option>Défense</option><option>Note personnelle</option></select></div><div class="field"><label for="event-impact">Impact</label><select id="event-impact" name="impact"><option value="neutral">Neutre</option><option value="positive">Positif</option><option value="negative">Négatif</option></select></div><div class="field full"><label for="event-desc">Détail</label><textarea id="event-desc" name="description" maxlength="800" required></textarea></div></div></form>`,modalFooter('Annuler','Ajouter au journal'));}
function openDateModal(){showModal('Modifier la date de simulation','La date permet de démarrer une chronologie spécifique. Les actions suivantes reprendront à partir de cette date.',`<form id="modalForm" data-form="date"><div class="form-grid"><div class="field"><label for="sim-day">Jour</label><input id="sim-day" name="day" type="number" min="1" max="31" value="${app.state.date.day}" required></div><div class="field"><label for="sim-month">Mois</label><input id="sim-month" name="month" type="number" min="1" max="12" value="${app.state.date.month}" required></div><div class="field"><label for="sim-year">Année</label><input id="sim-year" name="year" type="number" min="1900" max="2200" value="${app.state.date.year}" required></div></div></form>`,modalFooter('Annuler','Modifier la date'));}
function openAlerts(){const s=app.state;showModal('Notifications et alertes',`${s.alerts.length} notification(s) non lue(s)`,s.alerts.length?s.alerts.map(a=>`<div class="list-row"><div class="list-icon">!</div><div class="list-content"><div class="list-title">${esc(a.title)}</div><div class="list-desc">${esc(a.description)}</div><div class="list-meta">${esc(a.date)}</div></div></div>`).join(''):emptyState('Aucune alerte non lue','Les alertes budgétaires, politiques et de projet apparaîtront ici.'),`<button class="button button-secondary" data-action="close-modal">Fermer</button><button class="button button-primary" data-action="clear-alerts">Tout marquer comme lu</button>`);}

function advanceDays(n){const s=app.state;const d=Math.max(1,Math.min(3650,Number(n)||1));for(let i=0;i<d;i++){const prevBal=s.finance.balance;s.finance.cash=round1(s.finance.cash+prevBal/365);s.finance.debt=Math.max(0,round1(s.finance.debt-prevBal/365)); // un déficit ajoute la dette; un excédent la réduit.
  s.date.day++;s.dayCount++;const daysInMonth=new Date(s.date.year,s.date.month,0).getDate();if(s.date.day>daysInMonth){s.date.day=1;s.date.month++;if(s.date.month>12){s.date.month=1;s.date.year++;}}
  // La trajectoire macroéconomique évolue lentement à chaque journée simulée.
  s.economy.gdp=Math.max(1,round1(s.economy.gdp*(1+s.society.growth/100/365)));s.society.population=Math.max(.1,round1(s.society.population*(1+s.society.migration/100/365)));s.society.unemployment=round1(Math.max(0,Math.min(50,s.society.unemployment+(s.society.growth<0?.001:-.0004))));
  s.projects.forEach(p=>{if(p.status==='En cours'&&p.progress<100){p.progress=Math.min(100,round1(p.progress+100/Math.max(1,p.duration)));p.spent=Math.min(p.budget,round1(p.budget*p.progress/100));if(p.progress>=100){p.status='Terminé';eventLog(`Projet achevé : ${p.title}`,`Le programme ${p.title} est marqué comme terminé.`,'investissement','positive');}}});
  s.procurement.orders.forEach(o=>{if(o.status==='Commandé'){o.daysLeft=Math.max(0,o.daysLeft-1);if(o.daysLeft===0){o.status='Livrée';s.procurement.stock[o.itemId]=(s.procurement.stock[o.itemId]||0)+o.quantity;eventLog(`Commande livrée : ${o.itemName}`,`${o.quantity} lot(s) ont été ajoutés au stock national.`,'achats','positive');s.alerts.unshift({id:makeId('a'),date:dstr(),title:'Commande livrée',description:`${o.itemName} — ${o.quantity} lot(s)`});}}});
  s.defense.units.forEach(u=>{if(u.destination){const a=u.destination;const diffLat=a.lat-u.lat,diffLng=a.lng-u.lng;u.lat=round1(u.lat+diffLat*.22);u.lng=round1(u.lng+diffLng*.22);u.moveProgress=Math.min(99,round1(100-Math.sqrt(diffLat*diffLat+diffLng*diffLng)/Math.max(.01,u.destination.distance||10)*100));if(Math.abs(diffLat)<.025&&Math.abs(diffLng)<.025){u.lat=a.lat;u.lng=a.lng;u.destination=null;u.moveProgress=100;u.status='Opérationnel';eventLog(`Déplacement terminé : ${u.name}`,`L’unité a atteint la destination définie dans la simulation.`,'défense','neutral');}}});
  // Les votes ont une durée symbolique d'un mois de simulation.
  s.bills.forEach(b=>{if(b.status==='En lecture'&&b.daysInStage!=null){b.daysInStage++;if(b.daysInStage>45)b.daysInStage=45;}});
  if(s.dayCount%30===0){s.finance.debtHistory.push(s.finance.debt);s.finance.debtHistory=s.finance.debtHistory.slice(-12);s.finance.spendHistory.push(s.finance.expenses);s.finance.spendHistory=s.finance.spendHistory.slice(-6);s.finance.revenueHistory.push(s.finance.revenue);s.finance.revenueHistory=s.finance.revenueHistory.slice(-6);s.finance.balanceHistory.push(s.finance.balance);s.finance.balanceHistory=s.finance.balanceHistory.slice(-12);s.political.stability=round1(Math.max(0,Math.min(100,s.political.stability+(s.finance.balance<0?-.15:.07)+(s.political.approval>=50?.04:-.08))));if(s.settings.randomEvents&&Math.random()<.34)generateRandomEvent();if(s.finance.cash<0){s.alerts.unshift({id:makeId('a'),date:dstr(),title:'Trésorerie négative',description:'Le solde de trésorerie est négatif. Étudiez un financement ou rééquilibrez le budget.'});s.finance.cash=Math.max(-9999,s.finance.cash);}}
  recalculate(s);
 }
 s.political.approval=round1(Math.max(0,Math.min(100,s.political.approval)));s.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Exécution budgétaire sur ${d} jour${d>1?'s':''}`,category:'Gestion courante',amount:round1((s.finance.revenue-s.finance.expenses)*d/365),balance:s.finance.cash});s.finance.transactions=s.finance.transactions.slice(0,100);recalculate(s);eventLog('Temps écoulé',`La simulation avance de ${d} jour${d>1?'s':''}. Le budget, les projets et les unités ont été mis à jour.`,'chronologie','neutral');saveState();render();toast(`Simulation avancée de ${d} jour${d>1?'s':''}.`,'success');}
function generateRandomEvent(){const s=app.state;const events=[
 {title:'Tensions sur les marchés de l’énergie',description:'La hausse des coûts pèse sur les prévisions économiques. Une réponse budgétaire est possible.',type:'Économie',impact:'negative',apply:()=>{s.society.inflation=round1(Math.min(20,s.society.inflation+.15));s.political.approval=round1(Math.max(0,s.political.approval-.5));}},
 {title:'Indicateurs de confiance en amélioration',description:'Les dernières décisions soutiennent la confiance dans les perspectives nationales.',type:'Économie',impact:'positive',apply:()=>{s.economy.confidence=round1(s.economy.confidence+.6);s.political.approval=round1(Math.min(100,s.political.approval+.3));}},
 {title:'Contestation sociale annoncée',description:'Des organisations syndicales annoncent une mobilisation autour des priorités économiques.',type:'Politique',impact:'negative',apply:()=>{s.political.stability=round1(Math.max(0,s.political.stability-.7));s.political.approval=round1(Math.max(0,s.political.approval-.4));}},
 {title:'Coopération bilatérale renforcée',description:'Un partenaire propose d’ouvrir des discussions sur la coopération scientifique et industrielle.',type:'Diplomatie',impact:'positive',apply:()=>{const p=Object.keys(s.diplomacy.relations)[Math.floor(Math.random()*Object.keys(s.diplomacy.relations).length)];s.diplomacy.relations[p]=Math.min(100,s.diplomacy.relations[p]+2);}},
 {title:'Alerte sur les dépenses de santé',description:'Les besoins de financement du système de santé font l’objet d’un débat au Parlement.',type:'Politique publique',impact:'negative',apply:()=>{s.political.approval=round1(Math.max(0,s.political.approval-.2));}}
];const e=events[Math.floor(Math.random()*events.length)];e.apply();eventLog(e.title,e.description,e.type,e.impact);s.alerts.unshift({id:makeId('a'),date:dstr(),title:e.title,description:e.description});s.alerts=s.alerts.slice(0,30);}
function voteBill(id){const s=app.state,b=s.bills.find(x=>x.id===id);if(!b)return;if(!['En lecture','Seconde lecture'].includes(b.status))return toast('Ce texte n’est pas en état d’être soumis au vote.','error');const secondReading=b.status==='Seconde lecture';const p=s.political.approval;const maj=s.political.seatBlocks.filter(x=>['majority','moderate'].includes(x.id)).reduce((n,x)=>n+x.seats,0)/Math.max(1,s.political.seatBlocks.reduce((n,x)=>n+x.seats,0));const yesChance=Math.max(.05,Math.min(.95,.2+p/200+maj*.35+(b.support-50)/180));const passed=Math.random()<yesChance;const yes=Math.round(s.parliament.totalSeats*yesChance);const no=s.parliament.totalSeats-yes;b.voteHistory=b.voteHistory||[];b.voteHistory.push({chamber:secondReading?'Seconde lecture':s.country.parliament,yes,no,passed});s.parliament.lastVote={title:b.title,result:passed?(secondReading?'Texte adopté en seconde lecture':'Texte adopté en première lecture'):(secondReading?'Texte rejeté en seconde lecture':'Texte rejeté en première lecture'),date:dstr()};if(passed&&!secondReading){b.status='Seconde lecture';b.daysInStage=0;eventLog(`Vote favorable : ${b.title}`,`Le texte est adopté en première lecture et transmis à la seconde lecture.`,'vote','positive');s.political.approval=round1(Math.min(100,s.political.approval+(b.support>=50?.5:-.5)));toast('Première lecture adoptée. Une seconde lecture est nécessaire.','success');}else if(passed&&secondReading){b.status='À signer';b.daysInStage=0;eventLog(`Texte adopté : ${b.title}`,`Le texte a franchi les lectures prévues et attend sa promulgation.`,'vote','positive');s.political.approval=round1(Math.min(100,s.political.approval+(b.support>=50?.5:-.5)));toast('Le texte est adopté et peut être promulgué.','success');}else{b.status='Rejeté';eventLog(`Rejet parlementaire : ${b.title}`,`Le projet de loi a été rejeté lors du vote parlementaire.`,'vote','negative');s.political.approval=round1(Math.max(0,s.political.approval-.7));toast('Le texte est rejeté par la chambre.','error');}saveState();render();}
function enactBill(id){const s=app.state,b=s.bills.find(x=>x.id===id);if(!b||b.status!=='À signer')return;b.status='Promulgué';b.promulgated=dstr();if(b.cost>0){const m=s.finance.ministries.find(x=>x.id==='other');m.budget=round1(m.budget+b.cost);}if(b.revenue>0)s.finance.otherRevenue=round1(s.finance.otherRevenue+b.revenue);s.political.approval=round1(Math.max(0,Math.min(100,s.political.approval+(b.support-50)*.025-(b.cost/Math.max(1,s.economy.gdp))*100)));recalculate(s);eventLog(`Promulgation : ${b.title}`,`Le texte est promulgué. Impact intégré au budget : coût ${billion(b.cost)} par an ; recette attendue ${billion(b.revenue)} par an.`,'législation','positive');s.alerts.unshift({id:makeId('a'),date:dstr(),title:'Loi promulguée',description:b.title});saveState();render();toast('La loi est promulguée et son impact budgétaire intégré.','success');}
function changeCountry(key){if(!COUNTRIES[key])return;closeModal();app.state=freshState(key);app.page='overview';saveState();render();toast(`Nouvelle campagne : ${COUNTRIES[key].short}.`,'success');}
function downloadFile(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvDownload(name,rows){const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');downloadFile(name,'\ufeff'+csv,'text/csv;charset=utf-8');}
function exportFinance(){const s=app.state;csvDownload('atlas-nations-comptes.csv',[['Date',dshort()],['Pays',s.country.name],['Indicateur','Valeur en milliards'],['PIB',s.economy.gdp],['Recettes',s.finance.revenue],['Dépenses',s.finance.expenses],['Solde',s.finance.balance],['Dette',s.finance.debt],['Trésorerie',s.finance.cash],[],['Mission','Crédit'],...s.finance.ministries.map(m=>[m.name,m.budget]),[],['Date','Opération','Catégorie','Montant','Solde après opération'],...s.finance.transactions.map(t=>[t.date,t.label,t.category,t.amount,t.balance])]);}
function exportBills(){const s=app.state;csvDownload('atlas-nations-lois.csv',[['Titre','Domaine','Résumé','Statut','Coût annuel','Recette annuelle','Soutien','Date de création'],...s.bills.map(b=>[b.title,b.sector,b.summary,b.status,b.cost,b.revenue,b.support,b.created])]);}
function exportProjects(){csvDownload('atlas-nations-projets.csv',[['Projet','Secteur','Statut','Budget','Dépensé','Avancement','Durée','Impact'],...app.state.projects.map(p=>[p.title,p.sector,p.status,p.budget,p.spent,p.progress,p.duration,p.impact])]);}
function exportEvents(){csvDownload('atlas-nations-journal.csv',[['Date','Type','Titre','Description','Impact'],...app.state.events.map(e=>[e.date,e.type,e.title,e.description,e.impact])]);}
function downloadSave(){downloadFile(`atlas-nations-${app.state.countryKey}-${app.state.date.year}${String(app.state.date.month).padStart(2,'0')}${String(app.state.date.day).padStart(2,'0')}.json`,JSON.stringify(app.state,null,2),'application/json;charset=utf-8');}
function updateMapMarkers(){if(!app.map||!app.mapReady)return;const existing=new Set(app.mapMarkers.keys());app.state.defense.units.forEach(u=>{existing.delete(u.id);let marker=app.mapMarkers.get(u.id);if(!marker){const div=document.createElement('div');div.className=`unit-marker ${u.destination?'mission':u.status==='En alerte'?'alert':'friendly'}`;div.textContent=({HQ:'QG',ARM:'T',AIR:'A',NAV:'N',LOG:'L'})[u.type]||'•';const icon=L.divIcon({className:'',html:div.outerHTML,iconSize:[27,27],iconAnchor:[13,13]});marker=L.marker([u.lat,u.lng],{icon}).addTo(app.map);app.mapMarkers.set(u.id,marker);marker.on('click',()=>selectUnit(u.id));}else{marker.setLatLng([u.lat,u.lng]);const div=document.createElement('div');div.className=`unit-marker ${u.destination?'mission':u.status==='En alerte'?'alert':'friendly'}`;div.textContent=({HQ:'QG',ARM:'T',AIR:'A',NAV:'N',LOG:'L'})[u.type]||'•';marker.setIcon(L.divIcon({className:'',html:div.outerHTML,iconSize:[27,27],iconAnchor:[13,13]}));}marker.bindPopup(`<strong>${esc(u.name)}</strong><br>${esc(u.status)}<br>Effectifs : ${integer(u.strength)}<br>Position : ${u.lat.toFixed(3)}, ${u.lng.toFixed(3)}${u.destination?'<br>Destination assignée':''}`);});existing.forEach(id=>{app.map.removeLayer(app.mapMarkers.get(id));app.mapMarkers.delete(id);});for(const [id,line] of app.mapRoutes){app.map.removeLayer(line);app.mapRoutes.delete(id);}app.state.defense.units.filter(u=>u.destination).forEach(u=>{const line=L.polyline([[u.lat,u.lng],[u.destination.lat,u.destination.lng]],{color:'#c18d47',weight:2,dashArray:'5 5',opacity:.9}).addTo(app.map);app.mapRoutes.set(u.id,line);});const selected=app.state.defense.units.find(u=>u.id===app.state.defense.selectedUnitId);if(selected&&document.getElementById('selectedUnitPanel'))document.getElementById('selectedUnitPanel').innerHTML=renderSelectedUnit();if(document.getElementById('unitList'))document.getElementById('unitList').innerHTML=renderUnitList();}
function initMap(){const el=document.getElementById('worldMap');if(!el)return;if(typeof L==='undefined'){el.innerHTML='<div class="empty-state"><strong>Chargement de la carte…</strong><p>La carte mondiale est chargée à la demande. Une connexion Internet est nécessaire pour les fonds cartographiques.</p></div>';const status=document.getElementById('mapStatus');if(status)status.textContent='Chargement du moteur cartographique…';if(!app.leafletLoading){app.leafletLoading=true;const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(css);const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.async=true;script.onload=()=>{app.leafletLoading=false;if(app.page==='defense')initMap();};script.onerror=()=>{app.leafletLoading=false;const mapEl=document.getElementById('worldMap');if(mapEl)mapEl.innerHTML='<div class="empty-state"><strong>La carte ne peut pas être chargée hors ligne</strong><p>Les autres pages restent disponibles. Revenez sur cette page avec une connexion Internet.</p></div>';const st=document.getElementById('mapStatus');if(st)st.textContent='Connexion cartographique indisponible';};document.body.appendChild(script);}return;}if(app.map&&app.map._container!==el){try{app.map.remove();}catch(e){}app.map=null;app.mapMarkers.clear();app.mapRoutes.clear();}if(!app.map){app.map=L.map(el,{worldCopyJump:true,zoomControl:true,preferCanvas:true}).setView(app.state.country.location,5);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(app.map);app.map.on('click',e=>{const u=app.state.defense.units.find(x=>x.id===app.state.defense.selectedUnitId);if(!u)return toast('Sélectionnez une unité avant de définir une destination.','error');u.destination={lat:round1(e.latlng.lat),lng:round1(e.latlng.lng)};u.status='En manœuvre';u.moveProgress=0;app.mapClickArmed=false;eventLog(`Ordre de déplacement : ${u.name}`,`Destination définie à ${u.destination.lat.toFixed(3)}, ${u.destination.lng.toFixed(3)}.`,'défense','neutral');saveState();updateMapMarkers();document.getElementById('mapStatus').textContent=`Destination définie pour ${u.name}. Faites avancer le temps pour suivre le déplacement.`;toast('Destination assignée. Avancez le temps pour suivre le mouvement.','success');});app.mapReady=true;}setTimeout(()=>{if(app.map)app.map.invalidateSize();},50);updateMapMarkers();const label=document.getElementById('mapStatus');if(label)label.textContent='Carte en ligne · positions de simulation · fonds OpenStreetMap';}
function selectUnit(id){app.state.defense.selectedUnitId=id;document.querySelectorAll('.unit-list-item').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));const u=app.state.defense.units.find(x=>x.id===id);if(u&&app.map)app.map.setView([u.lat,u.lng],Math.max(app.map.getZoom(),5));updateMapMarkers();saveState();}
function moveUnitInstant(id){const u=app.state.defense.units.find(x=>x.id===id);if(!u)return;u.destination=null;u.moveProgress=100;render();}
function confirmReset(){showModal('Recommencer une campagne','Cette opération supprime toute la partie actuelle. Exportez d’abord la sauvegarde si vous souhaitez la conserver.',`<div class="danger-zone"><strong>Attention : opération irréversible</strong><p>Les projets, textes de loi, contrats, unités et événements de la campagne actuelle seront remplacés.</p><div class="field"><label for="reset-country">Pays de la nouvelle campagne</label><select id="reset-country">${Object.entries(COUNTRIES).map(([k,c])=>`<option value="${k}" ${k===app.state.countryKey?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>`,`<button class="button button-secondary" data-action="close-modal">Annuler</button><button class="button button-danger" data-action="confirm-reset">Effacer et recommencer</button>`);}

// Navigation and UI actions are delegated to keep the project simple to edit.
document.addEventListener('click',e=>{
 const page=e.target.closest('[data-page]');if(page){if(!PAGE_INFO[page.dataset.page])return;app.page=page.dataset.page;document.getElementById('sidebar').classList.remove('open');render();return;}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,val=el.dataset.value;
 if(a==='close-modal'){closeModal();return;}if(a==='backdrop-close'&&e.target===el){closeModal();return;}
 switch(a){
  case'toggle-sidebar':document.getElementById('sidebar').classList.toggle('open');break;
  case'advance-day':advanceDays(1);break;case'advance-month':advanceDays(30);break;
  case'open-country':openCountryModal();break;case'choose-country':changeCountry(val);break;
  case'new-bill':openBillModal(null,el.dataset.sector||'');break;case'edit-bill':openBillModal(id);break;case'submit-bill':{const b=app.state.bills.find(x=>x.id===id);if(!b)return;b.status='En lecture';b.daysInStage=0;eventLog(`Texte déposé : ${b.title}`,`Le projet a été enregistré à l’ordre du jour du Parlement.`,'législation','neutral');saveState();render();toast('Projet de loi déposé au Parlement.','success');break;}
  case'vote-bill':voteBill(id);break;case'promulgate-bill':enactBill(id);break;case'withdraw-bill':{const b=app.state.bills.find(x=>x.id===id);if(b){b.status='Retiré';eventLog(`Retrait du texte : ${b.title}`,'Le texte a été retiré par l’exécutif.','législation','neutral');saveState();render();}break;}
  case'delete-bill':{if(confirm('Supprimer définitivement ce projet de loi ?')){app.state.bills=app.state.bills.filter(x=>x.id!==id);saveState();render();}break;}
  case'filter-bills':app.selectedBillFilter=val;render();break;
  case'new-project':openProjectModal();break;case'purchase-item':openPurchaseModal(id);break;case'cancel-order':{const o=app.state.procurement.orders.find(x=>x.id===id);if(!o||o.status!=='Commandé')break;if(!confirm('Annuler cette commande ? Une pénalité simulée de 15 % sera retenue.'))break;const refund=round1(o.cost*.85);app.state.finance.cash=round1(app.state.finance.cash+refund);o.status='Annulée';o.refund=refund;app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Annulation commande #${o.number}`,category:'Achats publics',amount:refund,balance:app.state.finance.cash});eventLog(`Commande annulée : ${o.itemName}`,`Remboursement après pénalité : ${billion(refund)}.`,'achats','neutral');saveState();render();toast('Commande annulée. Remboursement partiel enregistré.','success');break;}case'export-orders':csvDownload('atlas-nations-commandes.csv',[['Numéro','Article','Fournisseur','Quantité','Coût','Date','Délai restant','Statut','Objet'],...app.state.procurement.orders.map(o=>[o.number,o.itemName,o.supplier,o.quantity,o.cost,o.created,o.daysLeft,o.status,o.note])]);break;case'edit-project':openProjectModal(id);break;case'suspend-project':{const p=app.state.projects.find(x=>x.id===id);if(p){p.status='Suspendu';eventLog(`Projet suspendu : ${p.title}`,'Les dépenses et l’avancement du projet sont gelés.','investissement','negative');saveState();render();}break;}
  case'resume-project':{const p=app.state.projects.find(x=>x.id===id);if(p){p.status='En cours';eventLog(`Projet repris : ${p.title}`,'Le projet reprend son avancement.','investissement','neutral');saveState();render();}break;}
  case'delete-project':if(confirm('Supprimer ce projet du portefeuille ?')){app.state.projects=app.state.projects.filter(x=>x.id!==id);saveState();render();}break;
  case'open-borrow':openBorrowModal();break;case'edit-ministry':openMinistryModal(id);break;case'edit-budget-all':openAllBudgetModal();break;
  case'repay-bond':{const b=app.state.finance.bonds.find(x=>x.id===id);if(!b)return;if(app.state.finance.cash<b.principal)return toast('Trésorerie insuffisante pour rembourser le capital intégral.','error');if(!confirm(`Rembourser le capital de ${billion(b.principal)} ?`))return;app.state.finance.cash=round1(app.state.finance.cash-b.principal);app.state.finance.debt=Math.max(0,round1(app.state.finance.debt-b.principal));app.state.finance.bonds=app.state.finance.bonds.filter(x=>x.id!==id);app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Remboursement : ${b.label}`,category:'Dette',amount:-b.principal,balance:app.state.finance.cash});eventLog('Remboursement d’emprunt',`Capital remboursé : ${billion(b.principal)}.`,'finances','positive');saveState();render();toast('Emprunt remboursé.','success');break;}
  case'reset-taxes':{const start=COUNTRIES[app.state.countryKey];app.state.finance.tax={...start.tax};recalculate(app.state);eventLog('Barèmes fiscaux restaurés','Les taux fiscaux ont été restaurés aux valeurs de départ de la campagne.','fiscalité');saveState();render();toast('Barèmes de départ restaurés.','success');break;}
  case'edit-society':openSocietyModal();break;case'new-unit':openUnitModal();break;case'edit-unit':openUnitModal(id);break;
  case'select-unit':selectUnit(id);break;case'delete-unit':{const u=app.state.defense.units.find(x=>x.id===id);if(!u)return;if(!confirm(`Dissoudre l’unité « ${u.name} » ?`))return;app.state.defense.units=app.state.defense.units.filter(x=>x.id!==id);if(app.state.defense.selectedUnitId===id)app.state.defense.selectedUnitId=app.state.defense.units[0]?.id||null;saveState();render();break;}
  case'cancel-move':{const u=app.state.defense.units.find(x=>x.id===id);if(u){u.destination=null;u.status='Opérationnel';u.moveProgress=0;saveState();render();}break;}
  case'reset-unit-positions':if(confirm('Restaurer les positions de départ des unités ?')){app.state.defense.units=clone(UNIT_TEMPLATES);app.state.defense.selectedUnitId=app.state.defense.units[0]?.id||null;app.state.defense.nextUnitNo=6;saveState();render();}break;
  case'map-home':if(app.map)app.map.setView(app.state.country.location,5);break;case'map-world':if(app.map)app.map.setView([18,0],2);break;
  case'apply-alert-level':{const level=document.getElementById('alertLevel')?.value;if(level){app.state.defense.alertLevel=level;app.state.political.stability=round1(Math.max(0,Math.min(100,app.state.political.stability+(level==='Maximum'?-1:level==='Renforcé'?-.2:.2))));eventLog('Niveau d’alerte mis à jour',`L’alerte nationale est réglée sur « ${level} ».`,'défense','neutral');saveState();render();toast('Niveau d’alerte enregistré.','success');}break;}
  case'new-deal':openDealModal();break;case'sign-deal':{const d=app.state.diplomacy.deals.find(x=>x.id===id);if(d){d.status='Signé';d.signed=dstr();app.state.diplomacy.relations[d.partner]=Math.min(100,(app.state.diplomacy.relations[d.partner]||50)+4);eventLog(`Accord signé avec ${d.partner}`,`${d.type} consacré à ${d.product}.`,'diplomatie','positive');recalculate(app.state);saveState();render();toast('Accord signé.','success');}break;}
  case'delete-deal':{const d=app.state.diplomacy.deals.find(x=>x.id===id);if(d&&confirm('Clôturer cet accord ?')){app.state.diplomacy.deals=app.state.diplomacy.deals.filter(x=>x.id!==id);recalculate(app.state);saveState();render();}break;}
  case'edit-tariffs':openTariffModal();break;case'edit-aid':openAidModal();break;
  case'new-minister':openMinisterModal();break;case'edit-minister':openMinisterModal(id);break;case'dismiss-minister':{const m=app.state.cabinet.find(x=>x.id===id);if(m&&confirm(`Révoquer ${m.name} de ses fonctions ?`)){app.state.cabinet=app.state.cabinet.filter(x=>x.id!==id);app.state.political.stability=round1(Math.max(0,app.state.political.stability-1));eventLog(`Départ du gouvernement : ${m.name}`,`${m.role} a été retiré du cabinet.`,'gouvernement','negative');saveState();render();}break;}
  case'edit-seats':openSeatModal();break;case'simulate-confidence':{const support=app.state.political.seatBlocks.filter(x=>['majority','moderate'].includes(x.id)).reduce((n,x)=>n+x.seats,0);const pass=support>=app.state.parliament.majorityThreshold;app.state.parliament.lastVote={title:'Vote de confiance au gouvernement',result:pass?'Confiance accordée':'Confiance non acquise',date:dstr()};if(pass)app.state.political.stability=round1(Math.min(100,app.state.political.stability+2));else app.state.political.stability=round1(Math.max(0,app.state.political.stability-5));eventLog('Vote de confiance',pass?'La majorité soutient le gouvernement.':'Le soutien parlementaire est insuffisant.','parlement',pass?'positive':'negative');saveState();render();toast(pass?'Le gouvernement obtient la confiance.':'Le gouvernement ne dispose pas d’une majorité suffisante.',pass?'success':'error');break;}
  case'export-finance':exportFinance();break;case'export-bills':exportBills();break;case'export-projects':exportProjects();break;case'export-events':exportEvents();break;case'export-save':downloadSave();break;
  case'import-save':document.getElementById('importFile').click();break;
  case'save-now':saveState(false);break;
  case'toggle-autosave':app.state.settings.autoSave=!app.state.settings.autoSave;saveState();render();break;case'toggle-random':app.state.settings.randomEvents=!app.state.settings.randomEvents;saveState();render();break;
  case'reset-campaign':confirmReset();break;case'confirm-reset':{const key=document.getElementById('reset-country')?.value||'france';localStorage.removeItem(SAVE_KEY);changeCountry(key);break;}
  case'new-event':openEventModal();break;case'open-alerts':openAlerts();break;case'clear-alerts':app.state.alerts=[];saveState();closeModal();render();toast('Notifications marquées comme lues.','success');break;
  case'set-date':openDateModal();break;case'campaign-fund':openCampaignFundModal();break;
  case'campaign-action':{const actions={tour:{label:'Déplacement national',cost:1.2,impact:1.4,desc:'Déplacements publics et rencontres territoriales.'},program:{label:'Présentation du programme',cost:.7,impact:1.0,desc:'Présentation publique des engagements et priorités.'},debate:{label:'Débat télévisé',cost:.4,impact:.7,desc:'Débat médiatique simulé.'},field:{label:'Campagne de terrain',cost:.8,impact:.8,desc:'Mobilisation des équipes et présence locale.'}};const c=actions[val];if(!c)break;if(app.state.political.campaignFund<c.cost)return toast('Budget de campagne insuffisant. Transférez des fonds avant de poursuivre.','error');app.state.political.campaignFund=round1(app.state.political.campaignFund-c.cost);const randomFactor=val==='debate'?(Math.random()<.45?-1:1):1;const delta=round1(c.impact*randomFactor);app.state.political.approval=round1(Math.max(0,Math.min(100,app.state.political.approval+delta)));app.state.political.polling.incumbent=round1(Math.max(0,Math.min(100,app.state.political.polling.incumbent+delta)));app.state.political.polling.opposition=round1(Math.max(0,100-app.state.political.polling.incumbent-(app.state.political.polling.undecided||0)));app.state.finance.cash=round1(app.state.finance.cash-c.cost);app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Action de campagne : ${c.label}`,category:'Campagne',amount:-c.cost,balance:app.state.finance.cash});eventLog(`Action de campagne : ${c.label}`,`${c.desc} Coût : ${billion(c.cost)}. Variation du sondage : ${delta>0?'+':''}${delta} point(s).`,'campagne',delta>=0?'positive':'negative');saveState();render();toast(`Action de campagne menée (${delta>0?'+':''}${delta} point(s)).`,'success');break;}
  case'simulate-election':{
   if(!confirm('Organiser le scrutin maintenant ? Le résultat changera la majorité et ouvrira un nouveau cycle électoral.'))break;
   const s=app.state,p=s.political;
   const incumbentShare=Math.max(5,Math.min(75,p.polling.incumbent+(Math.random()*6-3)+(p.stability-50)*.04));
   const won=incumbentShare>=50;
   const governingShare=won?incumbentShare:100-incumbentShare;
   const total=s.country.seats;
   const governmentSeats=Math.max(1,Math.min(total-1,Math.round(total*(.5+(governingShare-50)*.012))));
   const remainder=total-governmentSeats;
   const blocks=p.seatBlocks;
   const government=blocks.find(x=>x.id==='majority');
   const centre=blocks.find(x=>x.id==='moderate');
   const left=blocks.find(x=>x.id==='left');
   const right=blocks.find(x=>x.id==='right');
   const other=blocks.find(x=>x.id==='other');
   government.seats=Math.round(governmentSeats*.76);centre.seats=governmentSeats-government.seats;
   left.seats=Math.round(remainder*.48);right.seats=Math.round(remainder*.40);
   other.seats=total-government.seats-centre.seats-left.seats-right.seats;
   if(!won)p.ruling='Coalition d’opposition';
   government.name='Majorité gouvernementale';centre.name='Centre & partenaires';left.name=won?'Gauche d’opposition':'Gauche';right.name=won?'Droite d’opposition':'Droite';
   p.polling.incumbent=round1(governingShare);p.polling.opposition=round1(100-governingShare);p.polling.undecided=0;
   p.lastElection={date:dstr(),winner:p.ruling,result:`${incumbentShare.toLocaleString('fr-FR',{maximumFractionDigits:1})} % des voix pour la majorité sortante`,voteShare:incumbentShare,governmentSeats};
   p.mandateStartYear=s.date.year;p.term='Nouveau mandat';
   const electionYear=s.date.year+(s.countryKey==='france'||s.countryKey==='canada'?5:4);p.electionDate=`${electionYear}-04-15`;p.campaignFund=0;
   p.approval=round1(Math.max(0,Math.min(100,p.approval+(won?4:-8))));
   s.parliament.lastVote={title:'Élection nationale',result:won?'La majorité sortante est reconduite':'Alternance politique',date:dstr()};
   recalculate(s);eventLog('Résultat électoral',`${won?'La majorité sortante est reconduite':'Une alternance politique a lieu'}. La nouvelle majorité compte ${integer(governmentSeats)} sièges. ${p.lastElection.result}.`,'élections',won?'positive':'negative');
   saveState();render();toast(won?'La majorité sortante est reconduite.':'Le scrutin entraîne une alternance politique.','success');break;
  }
  
  default:break;
 }
});

document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const fd=new FormData(form);const d=Object.fromEntries(fd.entries());const num=k=>Number(d[k]||0);
 switch(form.dataset.form){
 case'tax':{const values={income:num('income'),corporate:num('corporate'),vat:num('vat'),fuel:num('fuel')};const limits={income:[0,60],corporate:[0,50],vat:[0,35],fuel:[0,60]};for(const[k,v]of Object.entries(values)){if(!Number.isFinite(v)||v<limits[k][0]||v>limits[k][1])return toast('Un taux fiscal dépasse les limites autorisées.','error');}app.state.finance.tax=values;recalculate(app.state);eventLog('Réforme des barèmes fiscaux','Les taux d’imposition ont été modifiés. Les recettes prévisionnelles ont été recalculées.','fiscalité','neutral');saveState();render();toast('Barèmes appliqués et recettes recalculées.','success');break;}
 case'bill':{if(!d.title.trim()||!d.summary.trim())return toast('Le titre et le résumé sont obligatoires.','error');const existing=d.id?app.state.bills.find(x=>x.id===d.id):null;const b={id:existing?.id||makeId('law'),title:d.title.trim(),sector:d.sector,summary:d.summary.trim(),support:Math.max(0,Math.min(100,num('support'))),cost:Math.max(0,num('cost')),revenue:Math.max(0,num('revenue')),status:existing?.status||'Brouillon',created:existing?.created||dstr(),voteHistory:existing?.voteHistory||[],daysInStage:existing?.daysInStage||0};if(existing)Object.assign(existing,b);else app.state.bills.unshift(b);eventLog(existing?'Projet de loi modifié':'Projet de loi rédigé',b.title,'législation','neutral');saveState();closeModal();render();toast(existing?'Modifications enregistrées.':'Brouillon de loi créé.','success');break;}
 case'project':{if(!d.title.trim())return toast('Le nom du projet est obligatoire.','error');const existing=d.id?app.state.projects.find(x=>x.id===d.id):null;const p={id:existing?.id||makeId('project'),title:d.title.trim(),sector:d.sector,priority:d.priority,budget:Math.max(.1,num('budget')),duration:Math.max(1,num('duration')),progress:Math.max(0,Math.min(100,num('progress'))),spent:existing?Math.min(num('budget'),round1(num('budget')*num('progress')/100)):round1(num('budget')*num('progress')/100),status:d.status,impact:d.impact.trim(),startDay:existing?.startDay??app.state.dayCount};if(p.progress>=100)p.status='Terminé';if(existing)Object.assign(existing,p);else app.state.projects.unshift(p);eventLog(existing?'Projet mis à jour':'Nouveau projet national',p.title,'investissement','neutral');saveState();closeModal();render();toast(existing?'Projet modifié.':'Projet créé.','success');break;}
 case'purchase':{const item=PROCUREMENT_CATALOG.find(x=>x.id===d.itemId);if(!item)return toast('Article inconnu.','error');const quantity=Math.max(1,Math.min(200,Math.trunc(num('quantity'))));const cost=round1(item.unitPrice*quantity);if(cost>app.state.finance.cash)return toast('Trésorerie insuffisante pour cette commande.','error');const order={id:makeId('order'),number:app.state.procurement.nextOrderNo++,itemId:item.id,itemName:item.name,category:item.category,supplier:d.supplier.trim()||item.supplier,quantity,unitPrice:item.unitPrice,cost,created:dstr(),daysLeft:item.delivery,status:'Commandé',note:d.note.trim()};app.state.finance.cash=round1(app.state.finance.cash-cost);app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Commande #${order.number} : ${order.itemName}`,category:'Achats publics',amount:-cost,balance:app.state.finance.cash});app.state.procurement.orders.unshift(order);eventLog(`Commande publique #${order.number}`,`${quantity} lot(s) de ${order.itemName} commandé(s) pour ${billion(cost)}. Livraison estimée dans ${item.delivery} jours.`,'achats','neutral');saveState();closeModal();render();toast('Commande enregistrée et trésorerie débitée.','success');break;}
 case'borrow':{const principal=num('principal'),rate=num('rate'),term=num('term');if(principal<=0||principal>2000||rate<0||rate>25)return toast('Vérifiez le capital et le taux saisis.','error');const loan={id:makeId('loan'),label:d.label.trim()||'Emprunt souverain',principal,rate,term,use:d.use,date:dstr()};app.state.finance.bonds.unshift(loan);app.state.finance.debt=round1(app.state.finance.debt+principal);app.state.finance.cash=round1(app.state.finance.cash+principal);const debtMin=app.state.finance.ministries.find(m=>m.id==='debt');if(debtMin)debtMin.budget=round1(debtMin.budget+principal*rate/100);app.state.finance.loanRate=rate;app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:`Emprunt : ${loan.label}`,category:'Financement',amount:principal,balance:app.state.finance.cash});eventLog('Financement souverain contracté',`${loan.label} : ${billion(principal)} sur ${term} ans à ${pct(rate)}. Affectation : ${loan.use}.`,'finances','neutral');recalculate(app.state);saveState();closeModal();render();toast('Emprunt enregistré. La dette et la trésorerie ont été mises à jour.','success');break;}
 case'unit':{const existing=d.id?app.state.defense.units.find(x=>x.id===d.id):null;const unit={id:existing?.id||makeId('unit'),name:d.name.trim(),type:d.type,status:d.status,strength:Math.max(1,num('strength')),readiness:Math.max(0,Math.min(100,num('readiness'))),lat:Math.max(-85,Math.min(85,num('lat'))),lng:Math.max(-180,Math.min(180,num('lng'))),destination:existing?.destination||null,moveProgress:existing?.moveProgress||0};if(existing)Object.assign(existing,unit);else{app.state.defense.units.push(unit);app.state.defense.selectedUnitId=unit.id;}eventLog(existing?'Unité mise à jour':'Nouvelle unité enregistrée',unit.name,'défense','neutral');saveState();closeModal();render();toast(existing?'Unité modifiée.':'Unité ajoutée à la carte.','success');break;}
 case'deal':{const deal={id:makeId('deal'),partner:d.partner,type:d.type,product:d.product,value:Math.max(0,num('value')),tariff:Math.max(0,Math.min(80,num('tariff'))),summary:d.summary.trim(),status:'En négociation',created:dstr()};app.state.diplomacy.deals.unshift(deal);eventLog(`Négociation ouverte avec ${deal.partner}`,`${deal.type} dans le secteur ${deal.product}.`,'diplomatie','neutral');saveState();closeModal();render();toast('Négociation créée. Vous pouvez maintenant signer l’accord.','success');break;}
 case'campaign-fund':{const amount=num('amount');if(amount<=0||amount>100)return toast('Montant non valide.','error');if(amount>app.state.finance.cash)return toast('La trésorerie disponible ne couvre pas ce transfert.','error');app.state.finance.cash=round1(app.state.finance.cash-amount);app.state.political.campaignFund=round1(app.state.political.campaignFund+amount);app.state.finance.transactions.unshift({id:makeId('tx'),date:dshort(),label:'Transfert vers le budget de campagne',category:'Campagne',amount:-amount,balance:app.state.finance.cash});eventLog('Financement de la campagne',`${billion(amount)} ont été transférés vers l’enveloppe de campagne.`,'campagne','neutral');saveState();closeModal();render();toast('Budget de campagne alimenté.','success');break;}
 case'society':{for(const k of Object.keys(app.state.society))if(d[k]!==undefined)app.state.society[k]=num(k);app.state.society.population=Math.max(.1,app.state.society.population);app.state.society.unemployment=Math.max(0,app.state.society.unemployment);app.state.society.inflation=Math.max(-10,app.state.society.inflation);app.state.economy.gdp=Math.max(1,app.state.economy.gdp);eventLog('Hypothèses socio-économiques modifiées','Les indicateurs nationaux ont été mis à jour manuellement.','économie','neutral');saveState();closeModal();render();toast('Indicateurs actualisés.','success');break;}
 case'ministry':{const m=app.state.finance.ministries.find(x=>x.id===d.id);if(m){const next=Math.max(0,num('budget'));eventLog('Arbitrage budgétaire',`${m.name} : ${billion(m.budget)} → ${billion(next)} par an.`,'finances','neutral');m.budget=next;recalculate(app.state);saveState();closeModal();render();toast('Crédit budgétaire mis à jour.','success');}break;}
 case'all-budget':{app.state.finance.ministries.forEach(m=>{if(d[m.id]!==undefined)m.budget=Math.max(0,num(m.id));});recalculate(app.state);eventLog('Budget révisé','Les crédits de plusieurs missions ont été ajustés.','finances','neutral');saveState();closeModal();render();toast('Budget révisé.','success');break;}
 case'minister':{const existing=d.id?app.state.cabinet.find(x=>x.id===d.id):null;const m={id:existing?.id||makeId('minister'),name:d.name.trim(),role:d.role.trim(),ministry:d.ministry.trim(),party:d.party.trim(),confidence:Math.max(0,Math.min(100,num('confidence')))};if(existing)Object.assign(existing,m);else app.state.cabinet.push(m);eventLog(existing?'Membre du gouvernement modifié':'Nomination au gouvernement',`${m.name} — ${m.role}.`,'gouvernement','neutral');saveState();closeModal();render();toast(existing?'Fiche du ministre mise à jour.':'Ministre nommé.','success');break;}
 case'seats':{app.state.political.seatBlocks.forEach(b=>b.seats=Math.max(0,num(b.id)));app.state.country.seats=app.state.political.seatBlocks.reduce((n,b)=>n+b.seats,0);recalculate(app.state);eventLog('Rapports de force révisés','La composition parlementaire de la simulation a été modifiée.','parlement','neutral');saveState();closeModal();render();toast('Composition parlementaire mise à jour.','success');break;}
 case'tariff':app.state.diplomacy.tariff=Math.max(0,Math.min(80,num('tariff')));eventLog('Droits de douane ajustés',`Taux moyen fixé à ${pct(app.state.diplomacy.tariff)}.`,'diplomatie');saveState();closeModal();render();toast('Droits de douane actualisés.','success');break;
 case'aid':app.state.diplomacy.aidBudget=Math.max(0,num('budget'));eventLog('Aide internationale ajustée',`Enveloppe annuelle fixée à ${billion(app.state.diplomacy.aidBudget)}.`,'diplomatie');saveState();closeModal();render();toast('Enveloppe d’aide actualisée.','success');break;
 case'event':eventLog(d.title.trim(),d.description.trim(),d.type,d.impact);saveState();closeModal();render();toast('Note ajoutée au journal.','success');break;
 case'date':{const year=Math.max(1900,Math.min(2200,Math.trunc(num('year')))),month=Math.max(1,Math.min(12,Math.trunc(num('month')))),maxDay=new Date(year,month,0).getDate(),day=Math.max(1,Math.min(maxDay,Math.trunc(num('day'))));app.state.date={year,month,day};eventLog('Date de simulation modifiée',`La chronologie reprend au ${dstr()}.`,'chronologie','neutral');saveState();closeModal();render();toast('Date de simulation modifiée.','success');break;}
 default:break;
 }
});

document.addEventListener('change',e=>{
 if(e.target.id==='importFile'&&e.target.files?.[0]){const file=e.target.files[0];const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(parsed.version!==3||!parsed.finance||!parsed.country||!parsed.date)throw new Error('format');app.state=parsed;saveState();closeModal();render();toast('Sauvegarde importée avec succès.','success');}catch(err){toast('Fichier invalide ou incompatible avec cette version.','error');}e.target.value='';};reader.readAsText(file);}
});

// Initialisation : une campagne est enregistrée à la première ouverture.
recalculate(app.state);
if(!localStorage.getItem(SAVE_KEY))saveState(true);
render();
